window.COURS = (window.COURS || []).concat([

/* ========= 8. LE VECTEUR VITESSE ET SA VARIATION ========= */
{
id:"vitesse", n:8, titre:"Le vecteur vitesse et sa variation",
sous:"Décrire un mouvement avec des flèches",
desc:"Référentiel, vecteur vitesse, construction sur une chronophotographie et variation du vecteur vitesse.",
duree:35,
sections:[
 {id:"s1", titre:"Aucun mouvement n'existe tout seul", blocs:[
  {t:"idee", x:"Un mouvement n'a de sens que **par rapport à quelque chose**. Ce quelque chose s'appelle le **référentiel**. Changer de référentiel change la description du mouvement — parfois du tout au tout."},
  {t:"p", x:"Assise dans un train, tu es immobile par rapport au wagon, et tu files à $300$ @u{km/h} par rapport aux rails. Les deux affirmations sont vraies en même temps : elles ne parlent simplement pas du même référentiel. C'est pour cela qu'un énoncé de physique commence toujours par préciser lequel il utilise."},
  {t:"p", x:"Changer de référentiel change aussi la **valeur** de la vitesse. Dans ce même train à $300$ @u{km/h}, lève-toi et marche vers l'avant à $5$ @u{km/h} par rapport au wagon : par rapport aux rails, tu vas à $300 + 5 = 305$ @u{km/h}. Vers l'arrière, tu vas à $300 - 5 = 295$ @u{km/h}. Tu as sûrement déjà vécu cette confusion : assise dans un train à quai, tu vois le train voisin démarrer et tu as l'impression de reculer. De même, si deux trains roulent côte à côte dans le même sens, à $300$ et $290$ @u{km/h}, un passager du plus lent voit l'autre le dépasser à $10$ @u{km/h} seulement. **Ce que cette règle simplifie** : elle ne vaut que si tout se passe sur une même ligne droite, et pour des vitesses bien inférieures à celle de la lumière, ce qui est toujours le cas dans la vie courante."},
  {t:"tbl", head:["Référentiel","Ce à quoi il est lié","Quand l'utiliser"], rows:[
   ["Terrestre","Le sol","Presque tous les mouvements de la vie courante"],
   ["Géocentrique","Le centre de la Terre, avec des axes pointés vers des étoiles lointaines (il ne tourne pas avec la Terre)","Mouvement des satellites, de la Lune"],
   ["Héliocentrique","Le centre du Soleil, avec des axes pointés vers des étoiles lointaines","Mouvement des planètes"]
  ]},
  {t:"piege", titre:"« Immobile » n'est jamais une réponse complète", x:"Écrire « le sac est immobile » ne veut rien dire. Il faut écrire « le sac est immobile **dans le référentiel du train** ». Un correcteur attend cette précision, et elle vaut souvent un point."}
  ,{t:"mots", items:[
   ["Référentiel","L'objet par rapport auquel on décrit le mouvement. Sans lui, dire « ça bouge » n'a aucun sens."],
   ["Trajectoire","La ligne dessinée par les positions successives du mobile. Elle change avec le référentiel choisi."],
   ["Chronophotographie","Une suite de positions enregistrées à intervalles de temps **égaux**. Des points serrés = lent, des points espacés = rapide."],
   ["Vecteur","Une flèche qui porte trois informations à la fois : une direction, un sens et une longueur."],
   ["Tangente","La direction que suit la courbe à l'endroit exact où on la regarde. C'est celle du vecteur vitesse."],
   ["Δ (delta)","Le symbole d'une **variation**, toujours « arrivée moins départ » : $Δt$ est une durée, et $Δ@v{v} = @v{v_{i+1}} - @v{v_i}$ la variation du **vecteur** vitesse. Attention : la valeur de $Δ@v{v}$ n'est pas toujours la différence des valeurs $v_{i+1} - v_i$. Sur un cercle parcouru à allure constante, $v_{i+1} - v_i = 0$, et pourtant $Δ@v{v}$ n'est pas nul. En ligne droite sans demi-tour, la valeur de $Δ@v{v}$ est l'**écart** entre les deux valeurs, compté positivement : pour un mobile qui passe de $8$ à $3$ @u{m/s}, elle vaut $5$ @u{m/s}."]
  ]}
 ]},

 {id:"s2", titre:"Le vecteur vitesse : trois informations d'un coup", blocs:[
  {t:"idee", x:"La vitesse ne se résume pas à un nombre. Une voiture à $50$ @u{km/h} qui tourne et une voiture à $50$ @u{km/h} qui va tout droit n'ont pas le même mouvement. Il faut donc un **vecteur**, qui porte trois informations à la fois."},
  {t:"formule", titre:"Ce que contient le vecteur vitesse $@v{v}$",
   x:"**direction** : la ligne selon laquelle l'objet avance à cet instant. On l'appelle la **tangente** à la trajectoire : c'est celle qu'il suivrait tout droit si plus rien ne le faisait tourner.<br>**sens** : lequel des deux côtés de cette ligne. Sur l'autoroute Paris–Lyon, à un endroit donné, la direction est la même pour tout le monde, mais le sens dit si l'on va vers Lyon ou vers Paris.<br>**valeur** : $v = @f{d}{Δt}$, en @u{m/s}, où $d$ est la distance parcourue pendant la durée $Δt$. C'est la vitesse **moyenne** sur cette durée ; elle donne la vitesse à un instant précis si $Δt$ est assez court.",
   note:"On note la valeur $v$ (sans flèche) et le vecteur $@v{v}$ (avec flèche). Les confondre coûte des points."},
  {t:"p", x:"La direction tangente mérite qu'on s'y arrête. Fais tourner une pierre au bout d'une ficelle, puis lâche : la pierre ne part ni vers le centre, ni en spirale. Vue de dessus, elle part **droit devant**, dans la direction tangente au cercle à l'instant du lâcher (le poids la fait ensuite retomber). C'est la preuve la plus simple que le vecteur vitesse est tangent à la trajectoire."},
  {t:"formule", titre:"Conversion à connaître par cœur", x:"$1$ @u{m/s} $= 3{,}6$ @u{km/h}", note:"En une heure il y a $3600$ @u{s}, dans un kilomètre $1000$ @u{m} : $1$ @u{m/s} fait $3600$ @u{m} par heure, soit $3{,}6$ @u{km/h}. Pour passer des @u{km/h} aux @u{m/s}, on **divise** par $3{,}6$ ; dans l'autre sens, on multiplie."},
  {t:"exemple", titre:"Exemple guidé — passer d'une unité à l'autre", enonce:"Une voiture roule à $90$ @u{km/h}. Quelle est sa vitesse en @u{m/s} ? Un sprinteur court $100$ @u{m} en $10$ @u{s} : quelle est sa vitesse en @u{km/h} ?", etapes:[
   {q:"La voiture", r:"On passe des @u{km/h} aux @u{m/s} : on divise par $3{,}6$. $v = @f{90}{3{,}6} = 25$ @u{m/s}."},
   {q:"Le sprinteur, en @u{m/s}", r:"$v = @f{d}{Δt} = @f{100}{10} = 10$ @u{m/s}."},
   {q:"Le sprinteur, en @u{km/h}", r:"On multiplie par $3{,}6$ : $v = 10 × 3{,}6 = 36$ @u{km/h}."},
   {q:"Le contrôle de bon sens", r:"Un nombre en @u{km/h} est toujours **plus grand** que le même en @u{m/s}. Si ta conversion donne l'inverse, tu as multiplié au lieu de diviser."}
  ]},
  {t:"p", x:"Une vitesse se lit aussi sur un **graphique** qui donne la position $x$ d'un objet en fonction du temps $t$. On lit deux positions à deux instants, puis on divise l'écart de position par l'écart de temps. Par exemple, si la position passe de $0$ @u{m} à $t = 0$ à $12$ @u{m} à $t = 3{,}0$ @u{s}, alors $v = @f{12 - 0}{3{,}0 - 0} = 4{,}0$ @u{m/s}, en moyenne sur cet intervalle. Sur le dessin, ce calcul se voit : c'est la **raideur** de la ligne, qu'on appelle sa **pente**. Si la ligne monte raide, l'objet gagne beaucoup de mètres à chaque seconde : il va vite. Si elle monte doucement, il va lentement. Si elle est **horizontale**, la position ne change plus : l'objet est arrêté. Et si la ligne est droite, la vitesse est la même tout du long."}
 ]},

 {id:"s3", titre:"Construire le vecteur vitesse sur une chronophotographie", blocs:[
  {t:"p", x:"Une **chronophotographie** est une série de positions enregistrées à intervalles de temps égaux, notés $τ$ (tau). Les points sont d'autant plus espacés que le mobile va vite : la figure contient donc déjà toute l'information sur la vitesse, il ne reste qu'à la lire."},
  {t:"fig", titre:"Lire une vitesse sur des positions successives",
   vue:[0,0,10,4], w:440, h:200, grille:false, axes:false,
   objets:[
    {t:"point", x:1, y:1.6, nom:"M₀", couleur:"ink3"},
    {t:"point", x:2.6, y:1.9, nom:"M₁", couleur:"ink3"},
    {t:"point", x:4.4, y:2.2, nom:"M₂", couleur:"ink"},
    {t:"point", x:6.4, y:2.5, nom:"M₃", couleur:"ink3"},
    {t:"point", x:8.6, y:2.8, nom:"M₄", couleur:"ink3"},
    /* le segment de référence et la vitesse qui en découle pulsent ensemble :
       c'est M₁M₃, mesuré une seule fois, qui donne directement v₂. */
    {t:"seg", de:[2.6,1.9], a:[6.4,2.5], couleur:"line2", pointille:true,
     anime:[{attr:"opacity", values:"1;0.35;1", dur:"1.6s"}]},
    {t:"vec", de:[4.4,2.2], a:[5.35,2.35], couleur:"vert", nom:"v₂",
     anime:[{attr:"stroke-width", values:"2.4;3.8;2.4", dur:"1.6s"}]},
    {t:"texte", x:4.5, y:0.9, txt:"même direction que M₁M₃, tracée depuis M₂", couleur:"ink2", taille:12}
   ],
   note:"Les points s'écartent de plus en plus : le mobile accélère. Le vecteur vitesse en M₂ a pratiquement la direction de M₁M₃. La longueur de la flèche verte représente la vitesse, à l'échelle choisie : elle n'est pas égale au segment."},
  {t:"p", x:"Les points sont numérotés dans l'ordre : $M_0$, $M_1$, $M_2$… Pour parler d'un point quelconque, on l'appelle $M_i$, où $i$ est son numéro. Celui d'avant est alors $M_{i-1}$, celui d'après $M_{i+1}$. Pour $M_2$, ce sont $M_1$ et $M_3$."},
  {t:"formule", titre:"Vitesse au point $M_i$",
   x:"$v_i ≈ @f{M_{i-1}M_{i+1}}{2τ}$",
   note:"On utilise les positions **encadrantes** : celle d'avant et celle d'après. C'est une approximation, d'autant meilleure que $τ$ est court."},
  {t:"p", x:"Pourquoi encadrer plutôt que prendre le segment suivant ? Parce qu'on veut la vitesse **au point $M_i$**, pas entre $M_i$ et $M_{i+1}$. C'est comme pour savoir à quelle allure tu passes devant un lampadaire : tu regardes où tu étais une seconde avant, où tu es une seconde après, et tu divises cette distance par deux secondes. Ton passage devant le lampadaire tombe pile au milieu de la mesure. Et comme on parcourt deux intervalles de temps, on divise par $2τ$ et non par $τ$."},
  {t:"exemple", titre:"Exemple guidé — calculer une vitesse ponctuelle", enonce:"Sur une chronophotographie prise toutes les $τ = 40$ @u{ms}, la distance $M_1M_3$ mesure $12$ @u{cm} en vraie grandeur. Quelle est la vitesse au point $M_2$ ?", etapes:[
   {q:"Convertir en unités du système", r:"$12$ @u{cm} $= 0{,}12$ @u{m} et $40$ @u{ms} $= 0{,}040$ @u{s}."},
   {q:"Écrire la formule", r:"$v_2 = @f{M_1M_3}{2τ}$."},
   {q:"Remplacer", r:"$v_2 = @f{0{,}12}{2 × 0{,}040} = @f{0{,}12}{0{,}080}$."},
   {q:"Calculer", r:"$v_2 = 1{,}5$ @u{m/s}, soit $5{,}4$ @u{km/h}."},
   {q:"L'erreur à ne pas faire", r:"Diviser par $τ$ au lieu de $2τ$ donnerait $3{,}0$ @u{m/s} : le double. La distance $M_1M_3$ a bien été parcourue en **deux** intervalles de temps."}
  ]},
  {t:"piege", titre:"L'échelle de la photo", x:"Sur une chronophotographie, les longueurs mesurées à la règle sont celles de l'image, pas de la réalité. L'énoncé donne toujours une **échelle** : $1$ @u{cm} sur la photo pour $10$ @u{cm} en réalité, par exemple. Oublier de l'appliquer fausse toutes les vitesses d'un même facteur."}
  ,{t:"figi", nom:"chronophoto"}
  ,{t:"p", x:"Déplace le point étudié : la flèche rouge encadre toujours ses deux voisins, et la flèche verte — le vecteur vitesse — s'allonge à mesure que le mobile va plus vite. Mets ensuite le gain de vitesse par seconde (des @u{m/s} gagnés chaque seconde, qu'on écrit @u{m/s²}) à zéro : les points s'espacent régulièrement et la flèche verte garde la même longueur d'un bout à l'autre."}
  ,{t:"methode", titre:"Calculer une vitesse sur une chronophotographie", etapes:[
   "**Repérer le point demandé**, disons $M_2$, et ses deux voisins $M_1$ et $M_3$.",
   "**Mesurer la distance $M_1M_3$ à la règle**, puis la convertir en distance réelle avec l'échelle de la photo.",
   "**Convertir en unités du système** : les mètres pour la distance, les secondes pour $τ$ (attention, il est souvent donné en @u{ms}).",
   "**Diviser par $2τ$** et non par $τ$ : la distance couvre **deux** intervalles de temps.",
   "**Vérifier l'ordre de grandeur** : quelques @u{m/s} pour un objet lancé à la main, quelques dizaines pour un véhicule."
  ], exemple:"$M_1M_3 = 0{,}12$ @u{m} réels, $τ = 40$ @u{ms} $= 0{,}040$ @u{s}. Alors $v_2 = @f{0{,}12}{2 × 0{,}040} = 1{,}5$ @u{m/s}."}
 ]},

 {id:"s4", titre:"La variation du vecteur vitesse", blocs:[
  {t:"idee", x:"Pourquoi s'intéresser à la **variation** de la vitesse plutôt qu'à la vitesse elle-même ? Parce que la vitesse seule ne dit rien des forces. Lance une balle vers le haut : pendant qu'elle monte, sa vitesse pointe vers le haut, alors que la seule force qui agit sur elle (en négligeant l'air), son poids, tire vers le bas. Autre exemple : une voiture sur l'autoroute, à $130$ @u{km/h} bien réguliers en ligne droite. Sa vitesse est grande, et pourtant les forces qui s'exercent sur elle se compensent. Ce qui trahit les forces, c'est la façon dont la vitesse **change**. Cette variation se note $Δ@v{v}$ : c'est la trace que les forces laissent sur le mouvement."},
  {t:"formule", titre:"Variation du vecteur vitesse",
   x:"$Δ@v{v} = @v{v_{i+1}} - @v{v_i}$",
   note:"C'est une **soustraction de vecteurs**, pas de nombres. On la construit géométriquement."},
  {t:"p", x:"Une façon de voir $Δ@v{v}$ : c'est **ce qu'il faut ajouter à l'ancienne vitesse pour obtenir la nouvelle**, $@v{v_i} + Δ@v{v} = @v{v_{i+1}}$. Imagine un palet de hockey qui glisse sur la glace, et toi avec ta crosse.<br>• Tu le frappes **par derrière**, dans son sens de marche : il repart plus vite, tout droit. $Δ@v{v}$ pointe **vers l'avant**.<br>• Tu le frappes **de face**, sans l'arrêter complètement : il ralentit. $Δ@v{v}$ pointe **vers l'arrière**.<br>• Tu le frappes **de côté** : il change de direction. $Δ@v{v}$ pointe **sur le côté**, là où tu l'as poussé.<br>En voiture, c'est pareil : l'accélérateur donne un $Δ@v{v}$ vers l'avant, le frein un $Δ@v{v}$ vers l'arrière, le volant un $Δ@v{v}$ vers l'intérieur du virage."},
  {t:"p", x:"**Ce que cette image simplifie.** Un coup de crosse est bref, et on a oublié le frottement de la glace. En réalité, $Δ@v{v}$ traduit l'effet de **toutes** les forces à la fois pendant l'intervalle. Autre nuance : un coup parfaitement de côté fait tourner le palet, mais l'accélère aussi un peu. Pour tourner **sans changer d'allure**, la poussée doit viser légèrement vers l'arrière. C'est ce que montre le troisième cas de la figure ci-dessous."},
  {t:"p", x:"La construction se fait en trois gestes, toujours les mêmes."},
  {t:"liste", items:[
   "**1.** Reporter les deux vecteurs $@v{v_i}$ et $@v{v_{i+1}}$ à partir d'un **même point d'origine**.",
   "**2.** Tracer la flèche qui va de la pointe de $@v{v_i}$ à la pointe de $@v{v_{i+1}}$.",
   "**3.** Cette flèche est $Δ@v{v}$ : c'est ce qu'il faut ajouter à l'ancien vecteur pour obtenir le nouveau, $@v{v_i} + Δ@v{v} = @v{v_{i+1}}$."
  ]},
  {t:"fig", titre:"Trois coups de crosse, trois Δv",
   vue:[0,0,15,6], w:540, h:250, grille:false, axes:false,
   objets:[
    {t:"seg", de:[4.9,0.3], a:[4.9,5.8], couleur:"line2", pointille:true},
    {t:"seg", de:[9.7,0.3], a:[9.7,5.1], couleur:"line2", pointille:true},
    /* cas 1 : il accélère — vᵢ=(2;0), Δv=(1,5;0), vᵢ₊₁=(3,5;0) */
    {t:"texte", x:2.35, y:5.5, txt:"1. Il accélère", couleur:"ink", taille:12.5},
    {t:"vec", de:[0.6,4.2], a:[2.6,4.2], couleur:"vert"},
    {t:"texte", x:1.6, y:4.45, txt:"vᵢ", couleur:"vert", taille:13},
    {t:"vec", de:[2.6,3.2], a:[4.1,3.2], couleur:"rouge"},
    {t:"texte", x:3.35, y:3.45, txt:"Δv", couleur:"rouge", taille:13},
    {t:"vec", de:[0.6,2.2], a:[4.1,2.2], couleur:"bleu"},
    {t:"texte", x:2.35, y:2.45, txt:"vᵢ₊₁", couleur:"bleu", taille:13},
    {t:"seg", de:[0.6,4.2], a:[0.6,2.2], couleur:"ink3", pointille:true},
    {t:"seg", de:[2.6,4.2], a:[2.6,3.2], couleur:"ink3", pointille:true},
    {t:"seg", de:[4.1,3.2], a:[4.1,2.2], couleur:"ink3", pointille:true},
    {t:"texte", x:2.35, y:0.9, txt:"Δv vers l'avant", couleur:"rouge", taille:12},
    /* cas 2 : il freine — vᵢ=(3,5;0), Δv=(−2;0), vᵢ₊₁=(1,5;0) */
    {t:"texte", x:7.15, y:5.5, txt:"2. Il freine", couleur:"ink", taille:12.5},
    {t:"vec", de:[5.4,4.2], a:[8.9,4.2], couleur:"vert"},
    {t:"texte", x:7.15, y:4.45, txt:"vᵢ", couleur:"vert", taille:13},
    {t:"vec", de:[8.9,3.2], a:[6.9,3.2], couleur:"rouge"},
    {t:"texte", x:7.9, y:3.45, txt:"Δv", couleur:"rouge", taille:13},
    {t:"vec", de:[5.4,2.2], a:[6.9,2.2], couleur:"bleu"},
    {t:"texte", x:6.15, y:2.45, txt:"vᵢ₊₁", couleur:"bleu", taille:13},
    {t:"seg", de:[5.4,4.2], a:[5.4,2.2], couleur:"ink3", pointille:true},
    {t:"seg", de:[8.9,4.2], a:[8.9,3.2], couleur:"ink3", pointille:true},
    {t:"seg", de:[6.9,3.2], a:[6.9,2.2], couleur:"ink3", pointille:true},
    {t:"texte", x:7.15, y:0.9, txt:"Δv vers l'arrière", couleur:"rouge", taille:12},
    /* cas 3 : virage à gauche, même allure — vᵢ=(2,7;−1,3), vᵢ₊₁=(2,7;1,3), Δv=(0;2,6) */
    {t:"texte", x:12.2, y:5.5, txt:"3. Il tourne, même allure", couleur:"ink", taille:12.5},
    {t:"point", x:10.4, y:3.2, couleur:"ink"},
    {t:"vec", de:[10.4,3.2], a:[13.1,1.9], couleur:"vert"},
    {t:"texte", x:11.6, y:2.05, txt:"vᵢ", couleur:"vert", taille:13},
    {t:"vec", de:[10.4,3.2], a:[13.1,4.5], couleur:"bleu"},
    {t:"texte", x:11.3, y:4.2, txt:"vᵢ₊₁", couleur:"bleu", taille:13},
    {t:"vec", de:[13.1,1.9], a:[13.1,4.5], couleur:"rouge",
     anime:[{attr:"stroke-width", values:"2.4;4;2.4", dur:"1.3s"}]},
    {t:"texte", x:13.6, y:3.2, txt:"Δv", couleur:"rouge", taille:13},
    {t:"texte", x:12.2, y:0.9, txt:"Δv vers l'intérieur", couleur:"rouge", taille:12}
   ],
   note:"Dans chaque cas, pars du point de départ, suis vᵢ puis Δv : tu arrives exactement à la pointe de vᵢ₊₁. C'est vᵢ + Δv = vᵢ₊₁. Dans les cas 1 et 2, les trois flèches devraient être superposées sur une même ligne : on les a écartées d'un étage pour les voir, et les pointillés verticaux relient les points qui sont en réalité confondus. Dans le cas 3, les deux vitesses ont exactement la même longueur, et pourtant Δv est loin d'être nul : il pointe vers l'intérieur du virage, à gauche du conducteur. L'angle est exagéré pour qu'on voie bien : plus les deux instants sont proches, plus Δv devient perpendiculaire à la vitesse."},
  {t:"fig", titre:"Le cas général : l'allure et la direction changent ensemble",
   vue:[0,0,8,5], w:400, h:250, grille:false, axes:false,
   objets:[
    {t:"vec", de:[1.5,1], a:[5,1.8], couleur:"vert", nom:"vᵢ"},
    {t:"vec", de:[1.5,1], a:[4,3.8], couleur:"bleu", nom:"vᵢ₊₁"},
    /* Δv pulse seul : c'est LE résultat de la construction, celui qui donne
       la direction de la somme des forces. */
    {t:"vec", de:[5,1.8], a:[4,3.8], couleur:"rouge", nom:"Δv",
     anime:[{attr:"stroke-width", values:"2.4;4;2.4", dur:"1.3s"}]},
    {t:"point", x:1.5, y:1, couleur:"ink"},
    {t:"texte", x:6.4, y:4.6, txt:"de la pointe de vᵢ", couleur:"ink3", taille:11.5},
    {t:"texte", x:6.4, y:4.1, txt:"vers celle de vᵢ₊₁", couleur:"ink3", taille:11.5}
   ],
   note:"Les deux vecteurs partent du même point. La flèche rouge les relie, dans le sens de la chronologie."},
  {t:"piege", titre:"Le sens de la flèche", x:"$Δ@v{v} = @v{v_{i+1}} - @v{v_i}$ va de la pointe de **l'ancien** vers la pointe du **nouveau**. Tracer la flèche dans l'autre sens donne un vecteur exactement opposé — et une conclusion inverse sur la force qui agit."},
  {t:"check", q:"Un palet glisse sur la glace vers l'**est** à $2$ @u{m/s}. Un coup de crosse le fait repartir vers le **nord**, toujours à $2$ @u{m/s}. Reporte les deux vitesses d'un même point : vers où pointe $Δ@v{v}$ ?",
   choix:["Vers le nord","Vers le nord-est","Nulle part : $Δ@v{v}$ est nul, la valeur n'a pas changé","Vers le nord-ouest"], bonne:3,
   expl:["Le nord, c'est la direction de la **nouvelle vitesse**, pas celle de sa variation. Depuis un même point, la pointe de l'ancienne flèche est à l'est, celle de la nouvelle au nord. Pour passer de l'une à l'autre, il faut monter **et** revenir vers l'ouest.",
         "Nord-est, ce serait plutôt la somme des deux vitesses. $Δ@v{v}$ est une différence : il va de la pointe de l'ancienne (vers l'est) à la pointe de la nouvelle (vers le nord).",
         "La valeur est la même, mais la direction a tourné d'un quart de tour. Le vecteur vitesse a donc changé, et $Δ@v{v}$ n'est pas nul. C'est le même piège que le cas 3 de la figure (il tourne, même allure).",
         "Exact. La flèche qui va de la pointe « est » à la pointe « nord » monte en revenant vers l'ouest : elle pointe vers le nord-ouest. Le coup de crosse a dû **annuler** le glissement vers l'est **et** en créer un vers le nord. Sa valeur : $2^2 + 2^2 = 8$, donc $Δv = @r{8} ≈ 2{,}8$ @u{m/s}, alors que la valeur de la vitesse n'a pas bougé."]}
  ,{t:"methode", titre:"Construire la variation du vecteur vitesse", etapes:[
   "**Tracer les deux vecteurs vitesse** $@v{v_i}$ et $@v{v_{i+1}}$ sur la figure, chacun à son point, tangents à la trajectoire, **avec leur longueur calculée par $v_i ≈ @f{M_{i-1}M_{i+1}}{2τ}$** et une même échelle.",
   "**Les reporter tous les deux à partir d'un même point** libre de la feuille, en gardant exactement leur direction et leur longueur.",
   "**Joindre les deux pointes** par une flèche allant de celle de $@v{v_i}$ vers celle de $@v{v_{i+1}}$ : c'est $Δ@v{v}$.",
   "**Lire sa direction**, et conclure sur les forces (la somme des forces, vue en Seconde, est reprise au chapitre suivant) : entre deux instants **proches**, la somme des forces a pratiquement la direction et le sens de $Δ@v{v}$. C'est même exact si elle garde la même direction pendant tout l'intervalle, comme en chute libre."
  ], exemple:"Sur la chronophotographie d'un ballon lancé, on trace $@v{v_i}$ et $@v{v_{i+1}}$ avec la méthode de la section précédente (direction de $M_{i-1}M_{i+1}$, longueur à l'échelle de $@f{M_{i-1}M_{i+1}}{2τ}$). La flèche qui joint leurs pointes est dirigée vers le bas : c'est la signature du poids (frottements de l'air négligés). La forme de la trajectoire ne suffit pas : ce sont les positions datées qui donnent les longueurs."},
  {t:"p", x:"C'est le cas 3 de la figure des trois coups de crosse : sur un manège qui tourne à allure constante, $Δ@v{v}$ n'est pas nul et, entre deux instants proches, il pointe vers le centre. La section suivante le montre en mouvement."}
 ]},

 {id:"s5", titre:"Ce que la variation raconte du mouvement", blocs:[
  {t:"tbl", head:["Mouvement","Le vecteur vitesse…","$Δ@v{v}$"], rows:[
   ["Rectiligne uniforme","garde direction, sens et valeur","**nul**"],
   ["Rectiligne accéléré","garde la direction, sa valeur augmente","dans le sens du mouvement"],
   ["Rectiligne ralenti","garde la direction, sa valeur diminue","dans le sens **opposé**"],
   ["Circulaire uniforme","garde sa valeur, change de direction","dirigé vers le **centre** (entre deux instants proches)"],
   ["Chute libre d'un objet lancé de biais (poids seul, air négligé : voir chapitre suivant)","change de valeur et de direction","dirigé vers le **bas**"]
  ]},
  {t:"idee", x:"Voici pourquoi tout cela compte : entre deux instants **proches**, la somme des forces qui s'exercent sur l'objet a pratiquement la direction et le sens de $Δ@v{v}$. C'est même exact quand la somme des forces garde la même direction pendant tout l'intervalle, comme en chute libre, où seul le poids agit. Attention : il faut connaître les **positions à des instants successifs**, comme sur une chronophotographie. Une trajectoire seule, sans les dates, ne suffit pas : sur une droite, elle ne dit même pas si l'objet accélère ou freine. C'est le pont vers le chapitre suivant, qui reprend la somme des forces vue en Seconde."},
  {t:"figi", nom:"chute"},
  {t:"p", x:"Sur cette figure, déplace les curseurs et observe : quels que soient la vitesse de départ et l'angle de lancer choisis, le vecteur rouge — la variation de vitesse — pointe **toujours vers le bas**. Il ne change jamais de direction. C'est la signature du poids, la seule force en jeu quand on néglige l'air : c'est ce qu'on appelle une **chute libre**, que le chapitre suivant précise. Comme le poids garde la même direction pendant tout le vol, la direction de $Δ@v{v}$ est ici **exactement** celle de la somme des forces."},
  {t:"p", x:"La ligne du tableau qui résiste le plus est celle du mouvement circulaire : comment une vitesse qui ne change pas de valeur peut-elle quand même varier ? La figure suivante répond en le montrant. Fais tourner le point sur le cercle, puis regarde les deux flèches reportées en bas à gauche : elles ont **toujours la même longueur** — la valeur de la vitesse est bien constante — et pourtant la flèche rouge qui les relie n'est jamais nulle."},
  {t:"figi", nom:"circulaire"},
  {t:"p", x:"Réduis maintenant l'angle parcouru jusqu'à sa plus petite valeur : la flèche rouge reportée devient presque perpendiculaire aux deux vitesses. Sur le cercle, la flèche rouge placée à mi-chemin entre les deux positions pointe vers le **centre**. C'est le résultat à retenir : entre deux instants proches, $Δ@v{v}$ pointe vers le centre. Il vaut pour la Lune autour de la Terre (orbite presque circulaire) comme pour un seau qu'on fait tourner au bout d'une corde : ce qui les maintient sur leur cercle est une force dirigée vers l'intérieur."},
  {t:"check", q:"Une bille roule à vitesse constante sur un cercle horizontal. Que vaut $Δ@v{v}$ entre deux instants voisins ?",
   choix:["Le vecteur nul, puisque la vitesse ne change pas","Un vecteur tangent au cercle","Un vecteur non nul, dirigé vers le centre du cercle","Un vecteur dirigé vers l'extérieur"], bonne:2,
   expl:["Attention : c'est la **valeur** qui ne change pas. Le vecteur, lui, change de direction à chaque instant — il reste tangent à un cercle, donc il tourne.",
         "Le vecteur **vitesse** est tangent au cercle. Sa **variation**, elle, est perpendiculaire à la vitesse et rentre vers le centre.",
         "Exact : la valeur de la vitesse ne change pas, mais sa direction, si. Le vecteur vitesse change donc, et sa variation pointe vers l'intérieur du cercle.",
         "Vers l'extérieur, la bille s'éloignerait du centre et quitterait le cercle. C'est le contraire qui se produit : quelque chose la ramène vers l'intérieur — la ficelle, le rail ou le frottement."]}
 ]},

 {id:"s6", titre:"Atelier — lire une vitesse sur une chronophotographie", blocs:[
  {t:"p", x:"Voici le même travail que dans l'exemple guidé, mais cette fois **c'est toi qui calcules**, avec d'autres nombres. Chaque étape attend une valeur ; tu n'accèdes à la suivante qu'une fois celle-ci trouvée. Si tu bloques, le coup de pouce est là, et « Voir cette étape » ne te fera pas perdre la face — mais essaie d'abord."},
  {t:"atelier", titre:"La vitesse d'un cycliste au point M₂",
   enonce:"Une chronophotographie est prise toutes les $τ = 50$ @u{ms}. Sur la photo, la distance $M_1M_3$ mesure $4{,}0$ @u{cm}. L'échelle indiquée est : $1$ @u{cm} sur la photo pour $20$ @u{cm} en réalité. On cherche la vitesse du cycliste au point $M_2$.",
   etapes:[
    {q:"Commence par convertir l'intervalle de temps : combien vaut $τ = 50$ @u{ms} en secondes ?",
     rep:0.05, tol:0.0005, unite:"s",
     aide:"Une milliseconde est un millième de seconde. On divise donc par mille.",
     diag:[{v:50, m:"$50$ est la valeur en millisecondes. On te demande la même durée exprimée en secondes."},
           {v:0.5, m:"Il manque un zéro : $50$ millisecondes, c'est $50 ÷ 1000 = 0{,}050$ @u{s}, pas $0{,}5$."},
           {v:5, m:"Attention à l'ordre de grandeur : cinquante millisecondes, c'est bien moins qu'une seconde."}],
     expl:"$50$ @u{ms} $= @f{50}{1000} = 0{,}050$ @u{s}. **Pourquoi commencer par là.** Toutes les formules de physique attendent des secondes ; garder des millisecondes donne un résultat mille fois trop grand. C'est l'erreur la plus coûteuse du chapitre, et elle se règle en première ligne."},

    {q:"Passe maintenant de la photo à la réalité : quelle est la vraie distance $M_1M_3$, en mètres ?",
     rep:0.80, tol:0.005, unite:"m",
     aide:"Chaque centimètre de la photo vaut 20 centimètres en vrai. Convertis ensuite le résultat en mètres.",
     diag:[{v:80, m:"$80$ centimètres, c'est juste — mais la question demande des **mètres**. Divise par cent."},
           {v:4, m:"$4{,}0$ @u{cm} est la mesure **sur la photo**. L'échelle n'a pas encore été appliquée."},
           {v:0.04, m:"Tu as converti les $4{,}0$ @u{cm} de la photo en mètres, sans appliquer l'échelle. Il faut d'abord multiplier par 20."}],
     expl:"$4{,}0$ @u{cm} sur la photo $× 20 = 80$ @u{cm} en réalité, soit $0{,}80$ @u{m}. **Pourquoi l'échelle est incontournable.** Une chronophotographie est une image réduite : la règle posée dessus ne mesure pas le monde, elle mesure le papier. Oublier l'échelle ne se voit pas dans le calcul — tout reste cohérent — mais fausse la vitesse d'un facteur 20 d'un bout à l'autre."},

    {q:"Quelle durée s'est écoulée entre le point $M_1$ et le point $M_3$ ?",
     rep:0.10, tol:0.0005, unite:"s",
     aide:"Compte les intervalles, pas les points : de $M_1$ à $M_2$, puis de $M_2$ à $M_3$.",
     diag:[{v:0.05, m:"$0{,}050$ @u{s} est la durée d'**un seul** intervalle. De $M_1$ à $M_3$, il y en a deux."},
           {v:0.15, m:"Tu as compté trois intervalles. Il y en a deux : $M_1 → M_2$ et $M_2 → M_3$."}],
     expl:"De $M_1$ à $M_3$, il y a **deux** intervalles : $2τ = 2 × 0{,}050 = 0{,}10$ @u{s}. **Le piège, et comment ne plus y tomber.** On compte spontanément les points — trois — au lieu des espaces entre eux — deux. Dessine trois croix et compte les segments : il y en a toujours un de moins que de croix. Diviser par $τ$ au lieu de $2τ$ double la vitesse trouvée."},

    {q:"Calcule enfin la vitesse au point $M_2$, en @u{m/s}.",
     rep:8, tol:0.2, unite:"m/s",
     aide:"La vitesse au point du milieu est la distance qui encadre ce point, divisée par la durée correspondante.",
     diag:[{v:16, m:"Tu as divisé par $τ$ au lieu de $2τ$ : le résultat est exactement doublé."},
           {v:0.125, m:"La division est inversée. C'est la distance qui va au numérateur : $@f{0{,}80}{0{,}10}$."},
           {v:4, m:"Tu as sans doute divisé par $0{,}20$ @u{s}, soit $4τ$. Il n'y a que deux intervalles entre $M_1$ et $M_3$."}],
     expl:"$v_2 = @f{M_1M_3}{2τ} = @f{0{,}80}{0{,}10} = 8{,}0$ @u{m/s}. **Pourquoi on encadre le point.** On ne peut pas mesurer une vitesse en un instant unique : il faut une distance et une durée, donc deux positions. En prenant celles qui **entourent** $M_2$, on obtient une valeur centrée sur lui, bien plus fidèle que si l'on prenait $M_2M_3$ seulement — qui donnerait la vitesse d'après $M_2$, pas la sienne."},

    {q:"Pour finir, traduis cette vitesse en @u{km/h}.",
     rep:28.8, tol:0.5, unite:"km/h",
     aide:"Pour passer des mètres par seconde aux kilomètres par heure, on multiplie par 3,6.",
     diag:[{v:2.22, m:"Tu as divisé par $3{,}6$. C'est la conversion dans l'autre sens, des @u{km/h} vers les @u{m/s}."},
           {v:8, m:"C'est la valeur en @u{m/s}, inchangée. Il reste la conversion à faire."}],
     expl:"$8{,}0 × 3{,}6 ≈ 29$ @u{km/h}. **D'où vient ce 3,6.** En une heure il y a $3600$ secondes, et dans un kilomètre $1000$ mètres : $@f{3600}{1000} = 3{,}6$. **Et pourquoi convertir.** $8{,}0$ @u{m/s} ne dit rien à personne ; $29$ @u{km/h} se reconnaît tout de suite : l'allure d'un cycliste rapide. Un résultat qu'on ne peut pas se représenter est un résultat qu'on ne peut pas vérifier."}
   ],
   bilan:"Retiens l'ordre : **on convertit d'abord, on calcule ensuite**. Les trois premières étapes ne contenaient aucune physique — que des unités et une échelle — et pourtant c'est là que se perdent la plupart des points. La physique proprement dite tenait en une division."}
 ]},

 {id:"s7", titre:"Récapitulatif", blocs:[
  {t:"liste", items:[
   "**1.** Préciser le référentiel avant toute description.",
   "**2.** Le vecteur vitesse est **tangent** à la trajectoire, orienté dans le sens du mouvement.",
   "**3.** Sur une chronophotographie : $v_i ≈ @f{M_{i-1}M_{i+1}}{2τ}$, sans oublier l'échelle ni le facteur 2.",
   "**4.** $Δ@v{v}$ se construit de la pointe de l'ancien vecteur vers la pointe du nouveau : $@v{v_i} + Δ@v{v} = @v{v_{i+1}}$.",
   "**5.** Entre deux instants proches, la somme des forces a pratiquement la direction et le sens de $Δ@v{v}$ (exactement si elle garde la même direction, comme en chute libre) : c'est ce qui rend cette construction si utile."
  ]},
  {t:"piege", titre:"Les erreurs les plus coûteuses", x:"**1.** Diviser par $τ$ au lieu de $2τ$ : la vitesse trouvée est doublée.<br>**2.** Oublier l'échelle de la chronophotographie.<br>**3.** Croire que $Δ@v{v}$ est nul dès que la valeur de la vitesse est constante — faux dans tout mouvement circulaire : $Δ@v{v}$ est une différence de **vecteurs**, pas de valeurs."}
 ]}
],
exos:[
 {id:"vi1", niveau:1, type:"num", enonce:"Une voiture roule à $108$ @u{km/h}. Quelle est sa vitesse en @u{m/s} ?",
  rep:30, tol:0.1, unite:"m/s",
  diag:[{v:388.8, m:"Tu as multiplié par $3{,}6$ au lieu de diviser. Un nombre en @u{km/h} est toujours plus grand que le même en @u{m/s} : la conversion doit donc **réduire** le nombre."},
        {v:1.8, m:"Tu as divisé par $60$, comme pour passer des heures aux minutes. Le facteur entre @u{km/h} et @u{m/s} est $3{,}6$ : il combine les $1000$ mètres du kilomètre et les $3600$ secondes de l'heure."},
        {v:10.8, m:"Tu as divisé par $10$. Le bon facteur est $3{,}6$."}],
  corr:["**Ce que dit l'énoncé.** Une vitesse de $108$ @u{km/h}. On la veut en @u{m/s}.",
        "**D'où vient le facteur $3{,}6$ ?** Un kilomètre vaut $1000$ mètres, une heure vaut $3600$ secondes. Passer des @u{km/h} aux @u{m/s} revient donc à multiplier par $@f{1000}{3600}$, c'est-à-dire à diviser par $3{,}6$.",
        "**Dans quel sens diviser ?** Un même mouvement donne toujours un **grand** nombre en @u{km/h} et un **petit** en @u{m/s}. Ici on va vers les @u{m/s} : le nombre doit diminuer, donc on divise.",
        "**Je pose le calcul.** $v = @f{108}{3{,}6}$.",
        "**Je calcule.** $108 ÷ 3{,}6 = 30$. Donc $v = 30$ @u{m/s}.",
        "**Je vérifie en sens inverse.** $30 × 3{,}6 = 108$ : je retombe sur la valeur de départ. Le résultat est bon."],
  indice:"$1$ @u{m/s} vaut $3{,}6$ @u{km/h} : la conversion vers les @u{m/s} donne un nombre plus petit."},

 {id:"vi2", niveau:1, type:"qcm", enonce:"Quelle est la direction du vecteur vitesse d'un point en mouvement ?",
  choix:["La perpendiculaire à la trajectoire","La tangente à la trajectoire","La droite qui joint le point au centre","Toujours l'horizontale"], bonne:1,
  diag:["La perpendiculaire à la trajectoire est la direction de la **variation** de vitesse dans un mouvement circulaire **uniforme**, entre deux instants proches — pas celle de la vitesse elle-même.",
        "",
        "C'est la direction du rayon dans un mouvement circulaire. La vitesse, elle, lui est perpendiculaire.",
        "Un objet lâché sans vitesse tombe verticalement : sa vitesse n'a rien d'horizontal. La direction dépend du mouvement, pas d'une orientation fixe."],
  corr:["**Ce que demande la question.** La direction du vecteur vitesse d'un point en mouvement.",
        "**Ce que représente ce vecteur.** Il indique où va le point **à l'instant considéré**, et à quelle allure.",
        "**Sur une trajectoire courbe.** Cette direction change en permanence : à chaque instant, elle suit la courbe là où le point se trouve.",
        "**Comment s'appelle cette direction ?** Celle qui épouse la courbe en un point est la **tangente** à la trajectoire.",
        "**L'expérience qui le prouve.** Fais tourner une pierre au bout d'une ficelle, puis lâche. Elle ne part ni vers le centre, ni en spirale : vue de dessus, elle part droit devant, selon la tangente au cercle à l'instant du lâcher.",
        "**Je conclus.** Le vecteur vitesse est **tangent à la trajectoire**, orienté dans le sens du mouvement."],
  indice:"Pense à une pierre qu'on lâche au bout d'une ficelle qu'on faisait tourner."},

 {id:"vi3", niveau:2, type:"num", enonce:"Sur une chronophotographie prise toutes les $τ = 50$ @u{ms}, la distance réelle $M_1M_3$ vaut $0{,}20$ @u{m}. Quelle est la vitesse au point $M_2$, en @u{m/s} ?",
  rep:2, tol:0.02, unite:"m/s",
  diag:[{v:4, m:"Tu as divisé par $τ$ au lieu de $2τ$. La distance $M_1M_3$ est parcourue en **deux** intervalles de temps, puisqu'elle enjambe $M_2$."},
        {v:0.5, m:"Tu as inversé la fraction : tu as calculé $@f{2τ}{d}$. La vitesse est une distance divisée par une durée."},
        {v:0.002, m:"Tu as gardé la durée en millisecondes tout en divisant comme si c'étaient des secondes. $50$ @u{ms} $= 0{,}050$ @u{s}."}],
  corr:["**Ce que dit l'énoncé.** Une chronophotographie prise toutes les $τ = 50$ @u{ms}, et une distance réelle $M_1M_3 = 0{,}20$ @u{m}. On cherche la vitesse **au point $M_2$**.",
        "**Pourquoi on encadre le point.** On veut la vitesse en $M_2$, pas entre deux positions. En prenant $M_1$ et $M_3$, le point d'intérêt se retrouve au **milieu** de l'intervalle de mesure : l'estimation est bien meilleure.",
        "**D'où vient le $2$ de la formule.** De $M_1$ à $M_3$, il s'écoule **deux** intervalles de temps : d'abord $M_1$ à $M_2$, puis $M_2$ à $M_3$. La durée totale est donc $2τ$, et la formule s'écrit $v_2 = @f{M_1M_3}{2τ}$.",
        "**Je convertis la durée.** $τ = 50$ @u{ms} $= 0{,}050$ @u{s}, donc $2τ = 0{,}10$ @u{s}.",
        "**Je remplace et je calcule.** $v_2 = @f{0{,}20}{0{,}10} = 2{,}0$ @u{m/s}.",
        "**Je vérifie l'ordre de grandeur.** $2$ @u{m/s} font environ $7$ @u{km/h} : l'allure d'un objet lancé à la main. Cohérent. Diviser par $τ$ au lieu de $2τ$ aurait donné le double, $4{,}0$ @u{m/s}."],
  indice:"Entre $M_1$ et $M_3$, il s'est écoulé deux intervalles de temps, pas un."},

 {id:"vi4", niveau:2, type:"qcm", enonce:"Un objet a un mouvement rectiligne uniforme. Que vaut la variation de son vecteur vitesse entre deux instants ?",
  choix:["Un vecteur dirigé vers l'avant","Un vecteur dirigé vers le bas","Un vecteur perpendiculaire au mouvement","Le vecteur nul"], bonne:3,
  diag:["Ce serait le cas d'un mouvement **accéléré**. « Uniforme » signifie justement que la valeur de la vitesse ne change pas.",
        "Un $Δ@v{v}$ vers le bas caractérise une chute libre (poids seul, voir chapitre suivant), où la vitesse change à cause du poids. Ici rien ne change.",
        "Une variation perpendiculaire au mouvement caractérise une trajectoire qui **tourne**. Ici la trajectoire est rectiligne.",
        ""],
  corr:["**Ce que dit l'énoncé.** Le mouvement est **rectiligne uniforme**. On cherche la variation du vecteur vitesse.",
        "**Je décompose les deux mots.** « Rectiligne » parle de la **direction** : la trajectoire est une droite, donc la direction ne change pas. « Uniforme » parle de la **valeur** : la vitesse ne ralentit ni n'accélère.",
        "**Ce qui reste du vecteur.** Direction constante, sens constant, valeur constante : les trois informations que porte le vecteur vitesse sont inchangées.",
        "**J'en déduis.** Le vecteur vitesse est rigoureusement le même d'un instant à l'autre : $@v{v_{i+1}} = @v{v_i}$.",
        "**Je calcule la variation.** $Δ@v{v} = @v{v_{i+1}} - @v{v_i} = @v{0}$. C'est le vecteur nul.",
        "**Ce que cela m'apprend en plus.** Le vecteur vitesse ne change pas : d'après le **principe d'inertie** (vu en Seconde, repris au chapitre suivant), la somme des forces est nulle — sans force, ou avec des forces qui se compensent, un objet garde exactement la même vitesse."],
  indice:"Décompose le mot : « rectiligne » parle de la direction, « uniforme » de la valeur."},

 {id:"vi5", niveau:2, type:"num", enonce:"Une voiture parcourt $450$ @u{m} en $30$ @u{s}. Quelle est sa vitesse moyenne en @u{km/h} ?",
  rep:54, tol:0.5, unite:"km/h",
  diag:[{v:15, m:"$15$ @u{m/s} est le bon résultat, mais dans la mauvaise unité. La question demande des @u{km/h} : il reste à multiplier par $3{,}6$."},
        {v:4.17, m:"Tu as divisé par $3{,}6$ au lieu de multiplier. On part de @u{m/s} pour aller vers les @u{km/h} : le nombre doit **augmenter**."},
        {v:0.067, m:"Tu as calculé $@f{Δt}{d}$. La vitesse est une distance divisée par une durée."}],
  corr:["**Ce que dit l'énoncé.** $450$ @u{m} parcourus en $30$ @u{s}. La réponse est attendue en @u{km/h}.",
        "**Le plan.** Je calcule d'abord la vitesse dans les unités des données (@u{m} et @u{s}), et je convertis ensuite. Mélanger les deux opérations est la meilleure façon de se tromper.",
        "**Étape 1 — la vitesse moyenne.** $v = @f{d}{Δt} = @f{450}{30}$.",
        "**Je calcule.** $v = 15$ @u{m/s}.",
        "**Étape 2 — la conversion.** On va des @u{m/s} vers les @u{km/h} : le nombre doit **augmenter**, donc on multiplie par $3{,}6$. $v = 15 × 3{,}6$.",
        "**Je calcule et je vérifie.** $v = 54$ @u{km/h} : l'allure d'une voiture sur une route. Plausible. Si j'avais divisé, j'aurais trouvé $4{,}2$ @u{km/h}, une allure de marche — invraisemblable pour $450$ @u{m} en $30$ @u{s}."],
  indice:"Calcule d'abord en @u{m/s}, puis convertis."},

 {id:"vi6", niveau:3, type:"qcm", enonce:"Une bille tourne à vitesse constante sur un cercle. Vers où pointe la variation de son vecteur vitesse, entre deux instants voisins ?",
  choix:["Dans le sens du mouvement","Elle est nulle","Vers le centre du cercle","Vers l'extérieur du cercle"], bonne:2,
  diag:["Dans le sens du mouvement, la bille irait de plus en plus vite. Or sa vitesse garde la même valeur.",
        "Ce serait vrai si le vecteur vitesse ne changeait pas du tout. Mais sa **direction** change en permanence, même si sa valeur reste la même.",
        "",
        "Vers l'extérieur, la bille s'éloignerait et quitterait le cercle. C'est l'inverse qui la maintient sur sa trajectoire."],
  corr:["**Ce que dit l'énoncé.** Une bille tourne à **vitesse constante** sur un cercle. On cherche la direction de $Δ@v{v}$.",
        "**Le piège.** « Vitesse constante » ne veut dire que **valeur** constante. Le vecteur, lui, comporte aussi une direction — et sur un cercle, cette direction tourne sans arrêt.",
        "**Étape 1 — je place les deux vecteurs.** À deux instants voisins, chacun est tangent au cercle, de même longueur, mais légèrement pivoté l'un par rapport à l'autre.",
        "**Étape 2 — je les reporte à partir d'un même point.** Deux flèches de même longueur, formant un petit angle entre elles.",
        "**Étape 3 — je joins les pointes**, de l'ancienne vers la nouvelle. La flèche obtenue est presque perpendiculaire aux deux, et pointe **vers l'intérieur** du cercle.",
        "**Je conclus, et j'en tire le sens physique.** Entre deux instants voisins, $Δ@v{v}$ est dirigé vers le centre. La somme des forces l'est donc aussi, pratiquement : c'est la ficelle, le rail ou le frottement qui retient la bille et l'empêche de partir tout droit."],
  indice:"Construis les deux vecteurs vitesse à partir d'un même point et regarde vers où pointe la flèche qui les relie."},

 {id:"vi7", niveau:3, type:"num", enonce:"Un mobile passe de $v_1 = 4{,}0$ @u{m/s} à $v_2 = 10{,}0$ @u{m/s} en ligne droite, en $2{,}0$ @u{s}. Quelle est la valeur de la variation de vitesse par seconde, en @u{m/s²} ?",
  rep:3, tol:0.05, unite:"m/s²",
  diag:[{v:6, m:"$6{,}0$ @u{m/s} est la variation **totale** de vitesse. La question demande la variation **par seconde** : il reste à diviser par la durée."},
        {v:7, m:"Tu as calculé la moyenne des deux vitesses. La variation est une différence, pas une moyenne."},
        {v:0.33, m:"Tu as inversé la fraction : $@f{Δt}{Δv}$. La variation par seconde est $@f{Δv}{Δt}$."}],
  corr:["**Ce que dit l'énoncé.** La vitesse passe de $4{,}0$ à $10{,}0$ @u{m/s} en $2{,}0$ @u{s}, en ligne droite. On cherche la variation **par seconde**.",
        "**Pourquoi je peux travailler sur les valeurs.** Le mouvement est rectiligne, sans demi-tour : la direction ne change pas, seule la valeur évolue. Ici, la valeur de $Δ@v{v}$ est l'écart entre les deux valeurs.",
        "**Étape 1 — la variation totale.** $Δv = v_{final} - v_{initial} = 10{,}0 - 4{,}0 = 6{,}0$ @u{m/s}. C'est ce que la vitesse a gagné en tout.",
        "**Étape 2 — ramener à une seconde.** Ces $6{,}0$ @u{m/s} ont été gagnés en $2{,}0$ @u{s}. Par seconde, cela fait $@f{6{,}0}{2{,}0}$.",
        "**Je calcule.** $3{,}0$ @u{m/s²}. La vitesse augmente de $3$ @u{m/s} chaque seconde. **D'où vient le m/s².** Des @u{m/s} gagnés **par seconde** : $@f{m/s}{s}$, que l'on écrit @u{m/s²}.",
        "**Je vérifie.** Après $1$ seconde : $4 + 3 = 7$ @u{m/s}. Après $2$ secondes : $7 + 3 = 10$ @u{m/s}. C'est bien la vitesse finale annoncée."],
  indice:"D'abord la variation totale, ensuite la division par la durée."},

 {id:"vi8", niveau:3, type:"txt", enonce:"Dans quel référentiel un passager assis dans un train en marche est-il immobile ? (quelques mots suffisent)",
  reps:["le train","train","referentiel du train","celui du train","wagon","siege","voiture","rame","tgv"],
  /* le moteur accepte toute saisie qui CONTIENT une réponse attendue, et
     teste les diagnostics dans l'ordre : « soleil » avant « sol » */
  diag:[{r:"soleil", m:"Dans le référentiel héliocentrique, lié au Soleil, le passager est emporté avec la Terre autour du Soleil : il n'y est pas immobile. Cherche le référentiel qui bouge **avec** lui."},
        {r:"helio", m:"Dans le référentiel héliocentrique, lié au Soleil, le passager est emporté avec la Terre autour du Soleil : il n'y est pas immobile. Cherche le référentiel qui bouge **avec** lui."},
        {r:"geocentr", m:"Dans le référentiel géocentrique, le passager est emporté par le train et par la rotation de la Terre : il n'y est pas immobile. Cherche le référentiel qui bouge **avec** lui."},
        {r:"terrestre", m:"Dans le référentiel terrestre, lié au sol, le passager défile à la vitesse du train : il n'y est pas immobile du tout. Cherche le référentiel qui bouge **avec** lui."},
        {r:"rail", m:"Les rails sont fixés au sol : par rapport à eux, le passager défile à la vitesse du train. Cherche le référentiel qui bouge **avec** lui."},
        {r:"gare", m:"La gare est immobile par rapport au sol : le passager y défile à la vitesse du train."},
        {r:"quai", m:"Le quai est immobile par rapport au sol : le passager y défile à la vitesse du train."},
        {r:"sol", m:"Par rapport au sol, le passager avance à la vitesse du train. Le référentiel où il est immobile est celui qui l'accompagne."}],
  corr:["**Ce que demande la question.** Dans quel référentiel un passager assis dans un train en marche est immobile.",
        "**Ce que veut dire « immobile ».** Un objet est immobile dans un référentiel si sa **position n'y change pas** au fil du temps. Sans référentiel précisé, le mot ne veut rien dire.",
        "**Je teste le référentiel terrestre.** Il est lié au sol, aux rails, au paysage. Par rapport à eux, le passager défile à la vitesse du train : il n'y est pas immobile.",
        "**Je teste le référentiel du train.** Il est lié au wagon, qui se déplace avec le passager. Par rapport à son siège, à la table, à la fenêtre, sa position ne change pas.",
        "**Je conclus.** Il est immobile dans le **référentiel du train** — et en mouvement dans le référentiel terrestre.",
        "**Ce qu'il faut retenir.** Les deux affirmations sont vraies **en même temps**. Elles ne se contredisent pas : elles ne parlent simplement pas du même référentiel."],
  indice:"Cherche le référentiel qui se déplace en même temps que lui."},

{id:"vi9", niveau:1, type:"num", enonce:"Un TGV file à $324$ @u{km/h}. Quelle distance parcourt-il en une seule seconde, en mètres ?",
  rep:90, tol:0.5, unite:"m",
  diag:[{v:324, m:"$324$ est la distance parcourue en une **heure**, et en kilomètres. La question porte sur une seconde."},
        {v:1166, m:"Tu as multiplié par $3{,}6$ au lieu de diviser. Vers les @u{m/s}, le nombre doit diminuer."},
        {v:5.4, m:"Tu as divisé par $60$, comme pour passer des heures aux minutes. Le facteur entre @u{km/h} et @u{m/s} est $3{,}6$."}],
  corr:["**Ce que dit l'énoncé.** Une vitesse en @u{km/h}. Ce qu'on cherche : une distance en mètres, parcourue en une seconde.",
        "**Le lien entre les deux.** Une vitesse en @u{m/s} est justement le nombre de mètres parcourus **par seconde**. Convertir la vitesse suffit donc à répondre.",
        "**Le facteur de conversion.** $1$ @u{m/s} $= 3{,}6$ @u{km/h}. Pour aller vers les @u{m/s}, on divise par $3{,}6$.",
        "**Je calcule.** $v = @f{324}{3{,}6} = 90$ @u{m/s}.",
        "**Je réponds à la question posée.** En une seconde, le train parcourt donc $90$ @u{m} — la longueur d'un terrain de football.",
        "**Je vérifie.** $90 × 3{,}6 = 324$ : je retombe sur la valeur de départ."],
  indice:"Une vitesse en @u{m/s}, c'est exactement le nombre de mètres parcourus en une seconde."},

 {id:"vi10", niveau:2, type:"num", enonce:"Sur une chronophotographie prise toutes les $τ = 25$ @u{ms}, la distance $M_1M_3$ mesure $3{,}0$ @u{cm} **sur la photo**. L'échelle est : $1$ @u{cm} sur la photo pour $10$ @u{cm} en réalité. Quelle est la vitesse au point $M_2$, en @u{m/s} ?",
  rep:6, tol:0.05, unite:"m/s",
  diag:[{v:0.6, m:"Tu as oublié d'appliquer l'échelle : $3{,}0$ @u{cm} sur la photo valent $30$ @u{cm} en réalité, soit dix fois plus. Ton résultat est dix fois trop petit."},
        {v:12, m:"Tu as divisé par $τ$ au lieu de $2τ$. La distance $M_1M_3$ enjambe le point $M_2$ : elle couvre **deux** intervalles de temps."},
        {v:3, m:"Tu as divisé par $4τ$, ou appliqué deux fois une division par 2. Il n'y a qu'un seul facteur 2 à placer."}],
  corr:["**Ce que dit l'énoncé.** Une longueur mesurée à la règle **sur la photo**, une échelle, et l'intervalle de temps entre deux positions.",
        "**Le piège de l'échelle.** Ce qu'on mesure à la règle n'est pas la distance réelle. L'échelle dit que chaque centimètre de photo vaut $10$ @u{cm} en vrai.",
        "**Je convertis en distance réelle.** $3{,}0$ @u{cm} $× 10 = 30$ @u{cm}, soit $0{,}30$ @u{m}.",
        "**Je convertis la durée.** $τ = 25$ @u{ms} $= 0{,}025$ @u{s}, donc $2τ = 0{,}050$ @u{s}.",
        "**J'applique la formule.** $v_2 = @f{M_1M_3}{2τ} = @f{0{,}30}{0{,}050}$.",
        "**Je calcule et je vérifie.** $v_2 = 6{,}0$ @u{m/s}, soit environ $22$ @u{km/h} : l'allure d'un objet lancé. Cohérent."],
  indice:"Trois étapes dans cet ordre : appliquer l'échelle, convertir la durée, puis diviser par $2τ$."},

 {id:"vi11", niveau:2, type:"qcm", enonce:"Une voiture roule en ligne droite et **freine**. Vers où pointe la variation de son vecteur vitesse $Δ@v{v}$ ?",
  choix:["Vers l'avant, dans le sens du mouvement","Vers l'arrière, en sens opposé au mouvement",
         "Elle est nulle","Perpendiculairement à la route"], bonne:1,
  diag:["Une variation vers l'avant ferait **accélérer** la voiture. Or elle freine : sa vitesse diminue.",
        "",
        "Une variation nulle signifierait une vitesse constante. Freiner, c'est justement faire varier la vitesse.",
        "Une variation perpendiculaire au mouvement fait **tourner** la trajectoire. Ici la voiture va tout droit."],
  corr:["**Ce que dit l'énoncé.** Trajectoire rectiligne, et vitesse qui **diminue**.",
        "**Je construis les deux vecteurs.** Ils ont la même direction et le même sens — la route est droite — mais le second est plus **court** que le premier.",
        "**Je les reporte à partir d'un même point.** Deux flèches alignées, l'une plus courte que l'autre.",
        "**Je joins les pointes**, de l'ancienne vers la nouvelle. Comme la nouvelle est plus courte, cette flèche pointe **vers l'arrière**.",
        "**Je conclus.** $Δ@v{v}$ est opposée au mouvement.",
        "**Ce que cela m'apprend sur les forces.** La somme des forces pointe dans le même sens que $Δ@v{v}$ : vers l'arrière. C'est l'action de la route sur les pneus — un frottement, que les freins déclenchent en ralentissant la rotation des roues — et, dans une moindre mesure, la résistance de l'air."],
  indice:"Les deux vecteurs sont alignés, mais le second est plus court. De quel côté va la flèche qui joint leurs pointes ?"},

 {id:"vi12", niveau:3, type:"num", enonce:"Un coureur parcourt $100$ @u{m} à $5{,}0$ @u{m/s}, puis $100$ @u{m} à $10{,}0$ @u{m/s}. Quelle est sa vitesse **moyenne** sur les $200$ @u{m}, en @u{m/s} ? (arrondis au dixième)",
  rep:6.7, tol:0.1, unite:"m/s",
  diag:[{v:7.5, m:"Tu as fait la moyenne des deux vitesses. C'est le piège de cet exercice : la vitesse moyenne n'est **pas** la moyenne des vitesses. Le coureur passe deux fois plus de temps sur la portion lente, qui pèse donc deux fois plus lourd."},
        {v:15, m:"Tu as additionné les deux vitesses. Une vitesse moyenne se calcule toujours par $@f{distance totale}{durée totale}$."},
        {v:5, m:"Tu as gardé la vitesse de la première portion. La moyenne doit être comprise entre $5$ et $10$ @u{m/s}."}],
  corr:["**La seule définition valable.** Vitesse moyenne $= @f{distance totale}{durée totale}$. Tout part de là — surtout pas d'une moyenne des vitesses.",
        "**La durée de la première portion.** $Δt_1 = @f{d}{v} = @f{100}{5{,}0} = 20$ @u{s}.",
        "**La durée de la seconde.** $Δt_2 = @f{100}{10{,}0} = 10$ @u{s}. Deux fois plus courte : il va deux fois plus vite.",
        "**La durée totale.** $20 + 10 = 30$ @u{s}, pour $200$ @u{m} parcourus.",
        "**Je calcule.** $v_{moy} = @f{200}{30} ≈ 6{,}7$ @u{m/s}.",
        "**Pourquoi ce n'est pas $7{,}5$.** Le coureur passe **deux fois plus de temps** à $5$ @u{m/s} qu'à $10$ @u{m/s} : la portion lente pèse deux fois plus dans la moyenne, qui penche donc vers le bas."],
  indice:"Calcule les deux durées séparément, puis divise la distance totale par la durée totale."},

{id:"vi13", niveau:2, type:"num", unite:"m/s",
  enonce:"Le graphique ci-dessous donne la position d'un mobile en fonction du temps. Quelle est sa vitesse entre $0$ et $4{,}0$ @u{s} ?",
  fig:{titre:"Document — position en fonction du temps", vue:[0,0,6.5,26], w:400, h:250,
       libre:true, grille:false, axes:false, objets:[
    {t:"axes", x0:0, y0:0, ax:"t (s)", ay:"x (m)"},
    {t:"courbeXY", pts:[[0,0],[4,20],[6,20]], couleur:"bleu", points:true, point:{dur:"2.6s"}},
    {t:"seg", de:[4,0], a:[4,20], couleur:"line2", pointille:true},
    {t:"seg", de:[0,20], a:[4,20], couleur:"line2", pointille:true},
    {t:"texte", x:4.45, y:1.6, txt:"4,0 s", couleur:"ink3", taille:11.5},
    {t:"texte", x:0.75, y:21.6, txt:"20 m", couleur:"ink3", taille:11.5}
   ], note:"Après 4 s, la courbe devient horizontale : le mobile s'est arrêté (modèle : on néglige la durée du freinage)."},
  rep:5, tol:0.1,
  diag:[{v:20, m:"$20$ @u{m} est la **distance** parcourue, lue sur l'axe vertical. La vitesse est cette distance divisée par la durée."},
        {v:80, m:"Tu as multiplié la distance par la durée. Une vitesse est un quotient : des mètres divisés par des secondes."},
        {v:0.2, m:"Tu as inversé la fraction ($@f{4{,}0}{20}$). Vérifie par les unités : des mètres divisés par des secondes donnent des @u{m/s}."}],
  corr:["**Je lis le document avant tout.** L'axe horizontal porte le temps en secondes, l'axe vertical la position en mètres.",
        "**Je repère les deux points utiles.** À $t = 0$, la position vaut $0$ @u{m}. À $t = 4{,}0$ @u{s}, elle vaut $20$ @u{m}.",
        "**J'en tire la distance parcourue.** $20 - 0 = 20$ @u{m}, en $4{,}0$ @u{s}.",
        "**J'applique la définition.** $v = @f{d}{Δt} = @f{20}{4{,}0}$.",
        "**Je calcule.** $v = 5{,}0$ @u{m/s}, soit $18$ @u{km/h}.",
        "**Je lis la suite du graphique.** Après $4$ @u{s}, la courbe devient **horizontale** : la position ne change plus, le mobile est à l'arrêt. La pente d'un graphique position-temps, c'est exactement la vitesse."],
  indice:"Lis la position au début et à la fin, puis divise l'écart par la durée."},

 {id:"vi14", niveau:2, type:"num", enonce:"Deux trains roulent parallèlement, dans le même sens, l'un à $90$ @u{km/h} et l'autre à $70$ @u{km/h} (par rapport au sol). Quelle est la vitesse du premier train dans le référentiel du second, en @u{km/h} ?",
  rep:20, tol:0.5, unite:"km/h",
  diag:[{v:160, m:"Tu as additionné les deux vitesses. Cela vaudrait si les deux trains roulaient en **sens opposés** l'un vers l'autre — ici ils vont dans le même sens."},
        {v:90, m:"$90$ @u{km/h} est la vitesse du premier train par rapport au **sol**, pas par rapport au second train."},
        {v:70, m:"$70$ @u{km/h} est la vitesse du second train par rapport au sol, pas la vitesse relative demandée."}],
  corr:["**Ce que demande la question.** La vitesse du premier train, mais mesurée dans un référentiel différent : celui du second train, pas celui du sol.",
        "**Changer de référentiel change la vitesse.** Les deux trains vont dans le même sens : vu depuis le second train, le premier semble avancer moins vite qu'il ne le ferait vu du sol.",
        "**Le calcul.** Dans le référentiel du second train, la vitesse du premier vaut la différence des deux vitesses au sol : $90 - 70 = 20$ @u{km/h}.",
        "**Le contrôle physique.** Un passager du train lent voit l'autre train le dépasser doucement, à $20$ @u{km/h} seulement — pas à $90$ @u{km/h}, sa vitesse par rapport au sol.",
        "**Et s'ils allaient en sens opposés ?** La vitesse relative serait alors la **somme** des deux, $90 + 70 = 160$ @u{km/h} : ce que ressent quelqu'un qui voit un train foncer vers lui à pleine vitesse combinée."],
  indice:"Deux mobiles allant dans le même sens : leur vitesse relative est la DIFFÉRENCE de leurs vitesses par rapport au sol, pas leur somme."},

 {id:"vi15", niveau:2, type:"qcm", enonce:"Un mobile a $v_i = 8{,}0$ @u{m/s}, puis un peu plus tard $v_{i+1} = 3{,}0$ @u{m/s}, sur une trajectoire rectiligne, toujours dans le même sens. Quel est le sens du vecteur $Δ@v{v}$ ?",
  choix:["Le sens opposé au mouvement, puisque le mobile ralentit",
         "Le même sens que le mouvement, puisque la vitesse a changé",
         "$Δ@v{v}$ est nul, puisque le mouvement reste rectiligne",
         "Impossible à savoir sans connaître la durée écoulée"], bonne:0,
  diag:["",
        "Le sens de $Δ@v{v}$ n'est pas automatiquement celui du mouvement : il dépend de si le mobile accélère ou ralentit. Ici la vitesse **diminue** ($8{,}0$ à $3{,}0$ @u{m/s}) : $Δ@v{v}$ pointe donc vers l'arrière.",
        "$Δ@v{v}$ est nul seulement si la vitesse — valeur, direction et sens — ne change pas du tout. Ici la valeur change : $Δ@v{v}$ est non nul.",
        "La durée n'intervient pas dans $Δ@v{v}$ : il se construit avec les deux seuls vecteurs vitesse. Elle ne servirait qu'à calculer ce que la vitesse perd **par seconde**, $@f{Δv}{Δt}$ — pas à trouver le sens de $Δ@v{v}$."],
  corr:["**Rappel de la construction.** $Δ@v{v} = @v{v_{i+1}} - @v{v_i}$ : une flèche qui va de la pointe de l'ancien vecteur vers la pointe du nouveau, les deux étant reportés à partir d'un même point.",
        "**Sur une trajectoire rectiligne, dans le même sens.** Les deux vecteurs $@v{v_i}$ et $@v{v_{i+1}}$ pointent dans la même direction et le même sens, mais $@v{v_{i+1}}$ est plus court : le mobile ralentit.",
        "**La flèche qui les relie.** Reportés à partir du même point, joindre la pointe du grand vecteur ($8{,}0$ @u{m/s}) vers la pointe du petit ($3{,}0$ @u{m/s}) donne une flèche dirigée en **arrière**, dans le sens opposé au mouvement.",
        "**Le lien avec le tableau du cours.** C'est exactement la ligne « rectiligne ralenti » : $Δ@v{v}$ dans le sens opposé au mouvement.",
        "**Pourquoi ça compte.** Entre deux instants proches, la somme des forces a pratiquement la direction et le sens de $Δ@v{v}$ : ici, une force qui s'oppose au mouvement — un freinage, un frottement."],
  indice:"Le mobile ralentit-il ou accélère-t-il ? Le sens de Δv dépend de cette seule question, pas de la durée écoulée."},

 {id:"vi16", niveau:3, type:"num", enonce:"Un ballon roule vers l'est à $v_i = 3{,}0$ @u{m/s}. Un joueur le frappe, et il repart vers le nord à $v_{i+1} = 4{,}0$ @u{m/s}. Quelle est la valeur de la variation de vitesse $Δ@v{v}$, en @u{m/s} ?",
  rep:5, tol:0.1, unite:"m/s",
  diag:[{v:1, m:"Tu as soustrait les valeurs : $4{,}0 - 3{,}0$. Cela ne marche qu'en ligne droite. Ici la direction a tourné d'un quart de tour : il faut construire la flèche $Δ@v{v}$."},
        {v:7, m:"Tu as additionné les valeurs. $Δ@v{v}$ est une différence de vecteurs : reporte les deux flèches d'un même point et mesure celle qui joint leurs pointes."},
        {v:25, m:"Tu as trouvé le carré de la valeur ($@u{m²/s²}$). Il reste à prendre la racine carrée."}],
  corr:["**Je reporte les deux vitesses d'un même point.** Une flèche de $3{,}0$ @u{m/s} vers l'est, une flèche de $4{,}0$ @u{m/s} vers le nord : elles forment un angle droit.",
        "**Je trace $Δ@v{v}$**, de la pointe de l'ancienne (est) vers la pointe de la nouvelle (nord). C'est l'hypoténuse d'un triangle rectangle de côtés $3{,}0$ et $4{,}0$.",
        "**Pythagore.** $Δv^2 = 3{,}0^2 + 4{,}0^2 = 9 + 16 = 25$.",
        "**Je calcule.** $Δv = @r{25} = 5{,}0$ @u{m/s}.",
        "**Le piège évité.** La valeur de la vitesse n'a changé que de $1{,}0$ @u{m/s}, et pourtant la valeur de $Δ@v{v}$ vaut $5{,}0$ @u{m/s}. La frappe a dû annuler le mouvement vers l'est **et** en créer un vers le nord : $Δ@v{v}$ pointe entre le nord et l'ouest, plus près du nord."],
  indice:"Les deux vitesses sont perpendiculaires. Dessine-les d'un même point : la flèche qui joint leurs pointes est l'hypoténuse d'un triangle rectangle."}
]
},

/* ======= 9. FORCES ET LOIS DE NEWTON ======= */
{
id:"forces", n:9, titre:"Forces et lois de Newton",
sous:"Ce qui met en mouvement, ce qui freine, ce qui fait tourner",
desc:"Modéliser une action par une force, principe d'inertie, deuxième loi de Newton, chute libre, gravitation et interaction électrostatique, actions réciproques.",
duree:35,
sections:[
 {id:"s1", titre:"Une force modélise une interaction", blocs:[
  {t:"idee", x:"Une **force** n'est jamais une propriété d'un objet : c'est la façon dont un objet **agit sur un autre**. Il faut donc toujours deux acteurs, et une force se nomme en les citant tous les deux."},
  {t:"p", x:"On écrit $@v{F}_{Terre/pomme}$ et jamais « la force de la pomme ». Cette écriture n'est pas un caprice de notation : elle oblige à identifier qui agit sur qui, ce qui évite d'inventer des forces qui n'existent pas."},
  {t:"p", x:"Une force se représente par un vecteur, avec les mêmes trois informations que le vecteur vitesse : une direction, un sens, et une valeur en **newtons** (@u{N}). La flèche part de l'objet qui **subit** la force, et sa longueur est proportionnelle à sa valeur : une force deux fois plus grande se dessine deux fois plus longue."},
  {t:"tbl", head:["Force","Direction et sens","Valeur"], rows:[
   ["Poids $@v{P}$","Verticale, vers le bas","$P = m × g$"],
   ["Réaction du support $@v{R}$","Perpendiculaire au support, vers l'extérieur (vers le haut pour un sol)","S'ajuste à la situation"],
   ["Tension d'un fil $@v{T}$","Selon le fil, vers le point d'attache","S'ajuste à la situation"],
   ["Frottement $@v{f}$","Parallèle au support, en sens **opposé** au glissement","S'ajuste à la situation"]
  ]},
  {t:"p", x:"Pourquoi « s'ajuste » ? Parce que ces forces de contact n'ont pas de valeur toute faite. Pose un livre sur ta main : elle pousse juste assez pour le porter. Pose-en un deuxième : elle pousse deux fois plus, sans que tu y penses. Une table fait la même chose, grâce à une infime déformation. Leur valeur ne se calcule donc pas avec une formule : on la **déduit** du mouvement, comme tu le feras dans l'atelier de fin de chapitre."},
  {t:"formule", titre:"Le poids", x:"$P = m × g$", note:"$P$ en @u{N} · $m$ en @u{kg} · $g$ s'appelle l'**intensité de la pesanteur**. Sur Terre, $g ≈ 9{,}81$ @u{N/kg}, ce qui se lit « newtons par kilogramme » : chaque kilogramme est tiré vers le bas avec une force de $9{,}81$ @u{N}. On prend souvent $10$ pour un calcul rapide. Sur la Lune, $g$ ne vaut que $1{,}6$ @u{N/kg}."},
  {t:"piege", titre:"Masse et poids ne sont pas la même chose", x:"La **masse** caractérise l'objet lui-même : elle se mesure en @u{kg}, avec une balance, et ne dépend pas de l'endroit où il se trouve. (Attention : en chimie, « quantité de matière » désigne autre chose, le nombre de moles $n$, vu au chapitre 1.) Le **poids** est une force : il se mesure en @u{N} et dépend de l'astre. Une élève de $50$ @u{kg} pèse $490$ @u{N} sur Terre et $80$ @u{N} sur la Lune — mais sa masse reste $50$ @u{kg} partout. Attention au langage courant : « je pèse 50 kilos » donne en réalité une **masse**. En physique, « peser » veut dire subir un poids, qui se compte en newtons."},
  {t:"p", x:"Un objet subit presque toujours **plusieurs** forces à la fois. Ce qui décide de son mouvement, c'est leur effet combiné : la **somme des forces**. Additionner des forces, ce n'est pas additionner des nombres : c'est mettre les flèches **bout à bout**, comme on enchaîne des déplacements sur une carte. Deux personnes qui tirent une barque dans le même sens : leurs flèches s'allongent l'une l'autre. Un tir à la corde entre deux équipes aussi fortes l'une que l'autre : les deux flèches ont la même longueur et des sens opposés ; mises bout à bout, elles reviennent au point de départ. La somme est nulle, on dit que les forces **se compensent**, et la corde ne bouge pas."},
  {t:"p", x:"On note cette somme $Σ@v{F}$ : $Σ$ est la lettre grecque « sigma », notre S, pour **S**omme. $Σ@v{F}$ se lit « somme des forces », et $ΣF$, sans flèche, désigne sa valeur en newtons. Quand elle est nulle, on écrit $Σ@v{F} = @v{0}$ : $@v{0}$ est le **vecteur nul**, une flèche de longueur zéro. Il ne reste plus rien à dessiner."}
  ,{t:"mots", items:[
   ["Force","La façon dont un objet agit sur un autre. Elle se note toujours en citant les deux : $@v{F}_{Terre/pomme}$."],
   ["Newton (@u{N})","L'unité des forces. Un newton, c'est à peu près le poids d'une petite pomme."],
   ["Système","L'objet dont on parle, et lui seul. On le choisit au début de l'exercice, et on n'en change plus."],
   ["Bilan des forces","La liste complète de ce qui agit sur le système : d'abord les contacts, ensuite les forces à distance."],
   ["Force de contact","Elle exige un contact : la réaction d'un support, la tension d'un fil, un frottement."],
   ["Force à distance","Elle agit sans contact : la gravitation (dont le poids est un cas particulier), l'attraction électrique."],
   ["Somme des forces ($Σ@v{F}$)","L'effet combiné de toutes les forces, obtenu en mettant leurs flèches bout à bout. $Σ$ (« sigma ») est le S grec, pour Somme."],
   ["Inertie","La tendance d'un objet à garder son mouvement tant que rien ne le change. C'est l'objet de la première loi de Newton."]
  ]},
  {t:"fig", titre:"Les forces sur un objet posé sur une table",
   vue:[0,0,8,6], w:340, h:250, grille:false, axes:false,
   objets:[
    {t:"sol", de:1, a:7, y:1.4},
    {t:"rect", x:3, y:1.4, w:2, h:1.2, couleur:"bleu"},
    {t:"texte", x:3.4, y:1.9, txt:"m", couleur:"bleu", taille:13},
    {t:"texte", x:3.6, y:0.6, txt:"P", couleur:"rouge", taille:14},
    /* les deux flèches pulsent EN PHASE, exactement ensemble : c'est ainsi
       qu'on VOIT qu'elles se compensent à chaque instant, pas seulement en
       moyenne. */
    {t:"vec", de:[4,2], a:[4,0.4], couleur:"rouge", anime:[{attr:"opacity", values:"1;0.4;1", dur:"1.4s"}]},
    {t:"vec", de:[4,2], a:[4,3.6], couleur:"vert", nom:"R", anime:[{attr:"opacity", values:"1;0.4;1", dur:"1.4s"}]},
    {t:"texte", x:6.4, y:3.9, txt:"R : la table pousse", couleur:"vert", taille:11.5},
    {t:"texte", x:6.3, y:0.7, txt:"P : la Terre attire", couleur:"rouge", taille:11.5}
   ],
   note:"Deux flèches de même longueur, en sens opposés : mises bout à bout, elles reviennent au point de départ. Leur somme est nulle, elles **se compensent** : le vecteur vitesse ne change pas. Posé immobile, l'objet reste immobile."}
 ]},

 {id:"s2", titre:"Le principe d'inertie : rien ne change sans raison", blocs:[
  {t:"formule", titre:"Première loi de Newton",
   x:"Si $Σ@v{F} = @v{0}$, alors le vecteur vitesse **ne change pas**.<br>Et dans l'autre sens : si le vecteur vitesse ne change pas, alors $Σ@v{F} = @v{0}$.",
   note:"« Le vecteur vitesse ne change pas » recouvre deux situations : l'objet reste **immobile**, ou il avance **en ligne droite à vitesse constante** (mouvement rectiligne uniforme). Pour les forces, c'est la même chose. Souviens-toi du train du chapitre précédent : une valise posée dans un train qui roule tout droit à vitesse constante est immobile par rapport au wagon, et file à $300$ @u{km/h} par rapport aux rails. Ce sont les mêmes forces qui agissent sur elle ; seul le point de vue a changé. Cette loi, comme la deuxième, s'applique dans le référentiel terrestre pour les objets proches du sol, et dans le référentiel géocentrique (chapitre précédent) pour la Lune et les satellites. On néglige pour cela, dans le premier cas, la rotation de la Terre sur elle-même, et dans le second, son mouvement autour du Soleil (voir l'exemple de la Lune, plus bas) : ni l'une ni l'autre ne change presque rien aux mouvements étudiés ici."},
  {t:"p", x:"Ce principe heurte l'intuition, et il a fallu deux mille ans pour l'admettre. Notre expérience quotidienne dit qu'il faut pousser pour qu'un objet continue d'avancer. Mais si l'objet ralentit dès qu'on cesse de pousser, ce n'est pas parce que le mouvement s'épuise : c'est parce que **les frottements agissent**. Sur une patinoire, où ils sont presque nuls, un palet lancé continue tout droit très longtemps."},
  {t:"astuce", titre:"La conséquence pratique", x:"Si tu constates qu'un objet va en ligne droite à vitesse constante, tu peux affirmer immédiatement que **la somme des forces est nulle**. Cela ne veut pas dire qu'il n'y a aucune force : cela veut dire qu'elles se compensent exactement, comme le poids et la réaction sur la table."}
  ,{t:"figi", nom:"bilan"}
  ,{t:"p", x:"Le poids et la réaction du sol se compensent en permanence — c'est pour cela que la caisse ne s'enfonce pas et ne décolle pas. Joue sur les deux forces horizontales : quand elles s'égalisent, la somme s'annule et le mouvement ne change plus, quelle que soit la vitesse déjà acquise."}
  ,{t:"methode", titre:"Faire le bilan des forces, sans en oublier", etapes:[
   "**Écrire le système étudié** en toutes lettres : « le système est la caisse ». Tout ce qui suit ne concerne qu'elle.",
   "**Chercher les contacts** : qu'est-ce qui touche le système ? Un support, un fil, l'air ? Chaque contact donne une force, parfois deux : le sol peut à la fois **porter** l'objet (réaction) et le **freiner** (frottement).",
   "**Ajouter les forces à distance** : sur Terre, il y a toujours le poids. Parfois une force électrique.",
   "**Dessiner chaque force par une flèche partant du centre de l'objet**, avec son nom.",
   "**Regarder si elles se compensent** : si oui, le vecteur vitesse ne change pas ; si non, il change dans la direction de leur somme."
  ], exemple:"Une caisse tirée sur le sol. Le sol la touche : il la porte (réaction) et la freine (frottement). La corde la touche et la tire (tension). À distance : le poids. Quatre forces, pas une de plus. L'air touche aussi la caisse, mais à si faible vitesse son effet est **négligeable** : si petit à côté des autres forces qu'on peut l'oublier sans changer la conclusion."},
  {t:"check", q:"Un parachutiste descend à vitesse constante. Que peut-on dire des forces qui s'exercent sur lui ?",
   choix:["Elles se compensent exactement","Seul le poids agit","La force de l'air est plus grande que le poids","Il n'y a aucune force"], bonne:0,
   expl:["Exact : vitesse constante et trajectoire rectiligne signifient $Σ@v{F} = @v{0}$. Le frottement de l'air compense exactement le poids.",
         "Si seul le poids agissait, il accélérerait sans cesse. C'est à peu près le cas dans les toutes premières secondes du saut, tant que sa vitesse est faible et que l'air le freine peu.",
         "Si la force de l'air l'emportait, il **ralentirait**. Or sa vitesse ne change pas : les deux forces sont égales.",
         "Le poids agit toujours. Ce qui est nul, c'est leur **somme**, pas chacune d'elles."]}
 ]},

 {id:"s3", titre:"La deuxième loi : les forces changent la vitesse", blocs:[
  {t:"idee", x:"Quand la somme des forces n'est pas nulle, le vecteur vitesse change — et il change **dans la direction et le sens de cette somme**. C'est la deuxième loi de Newton, le principe le plus utile de toute la mécanique."},
  {t:"p", x:"Et de combien la vitesse change-t-elle ? Pousse un caddie vide, puis le même caddie chargé de packs d'eau, avec la même force et pendant la même seconde (en négligeant les frottements des roues) : le vide gagne beaucoup plus de vitesse. Pousse deux fois plus fort le caddie vide : il gagne deux fois plus de vitesse. La variation de vitesse grandit avec la force, grandit avec la durée de la poussée, et diminue avec la masse : un objet lourd est plus difficile à faire changer de vitesse. C'est ce que résume la relation ci-dessous."},
  {t:"formule", titre:"Deuxième loi de Newton (version de Première : relation approchée)",
   x:"$Σ@v{F}$ et $Δ@v{v}$ ont **même direction et même sens**",
   note:"$Δ@v{v}$ est la variation du vecteur vitesse construite au chapitre précédent, et $Δt$ la durée pendant laquelle elle se produit, en secondes. Pour aller plus loin que la seule direction : $Σ@v{F} ≈ m × @f{Δ@v{v}}{Δt}$, pour un objet de masse $m$ constante, entre deux instants **proches**. L'égalité devient exacte si la somme des forces reste constante pendant $Δt$. Unités : $Δv$ (sans flèche, la valeur de cette variation) en @u{m/s}, $Δt$ en @u{s}, donc $@f{Δv}{Δt}$ en @u{m/s²} ; et $1$ @u{N} $= 1$ @u{kg·m/s²}, ce qui fait bien sortir la force en newtons."},
  {t:"p", x:"Le quotient $@f{Δv}{Δt}$ a une unité qui fait peur, @u{m/s²}, mais elle se lit comme une phrase : « des @u{m/s} gagnés **par seconde** ». Une voiture qui passe de $0$ à $30$ @u{m/s} (environ $110$ @u{km/h}) en $10$ @u{s} gagne $3$ @u{m/s} à chaque seconde : $3$ @u{m/s²}. Il y a une seconde dans la vitesse (@u{m/s}) et une seconde dans « chaque seconde » : les deux se regroupent en $s × s = s^2$, d'où le petit $²$."},
  {t:"p", x:"Lis bien ce que dit cette loi, et surtout ce qu'elle ne dit pas. Elle ne dit **pas** que la force donne la direction du mouvement : elle dit qu'elle donne la direction du **changement** de mouvement. Une balle lancée vers le haut monte encore alors que son poids est déjà dirigé vers le bas — le poids ne la fait pas descendre immédiatement, il ralentit sa montée, puis inverse le mouvement."},
  {t:"tbl", head:["Situation","$Σ@v{F}$","Effet sur le vecteur vitesse"], rows:[
   ["Voiture qui démarre","Vers l'avant","Sa valeur augmente"],
   ["Voiture qui freine","Vers l'arrière","Sa valeur diminue"],
   ["Bille au bout d'une ficelle, à vitesse constante sur une table horizontale","Vers le centre","Sa direction tourne, sa valeur ne change pas"],
   ["Balle lancée en l'air (air négligé)","Vers le bas, toujours","Elle ralentit, s'arrête, puis redescend"]
  ]},
  {t:"astuce", titre:"Le raisonnement à double sens", x:"Cette loi se lit dans les deux sens, et c'est ce qui la rend si puissante. **Des forces vers le mouvement** : je connais les forces, j'en déduis comment la vitesse va changer. **Du mouvement vers les forces** : je vois une trajectoire se courber vers la gauche, j'en déduis qu'une force tire vers la gauche. C'est ainsi qu'on a découvert Neptune en 1846. La planète Uranus ne suivait pas exactement la trajectoire prévue : elle était déviée d'un côté. Une déviation, c'est une force ; entre astres, une force à distance, c'est la gravitation d'une autre masse. L'astronome Le Verrier a calculé où devait se trouver cet astre inconnu. On a pointé un télescope à cet endroit, et Neptune y était."},
  {t:"methode", titre:"Utiliser la deuxième loi de Newton", etapes:[
   "**Repérer ce que l'énoncé donne** : les forces, ou bien la façon dont la vitesse change ? C'est ce qui décide du sens de lecture.",
   "**Si on donne les forces** : en faire la somme, et conclure que $Δ@v{v}$ a la même direction et le même sens. Puis comparer cette somme au mouvement. **Dans le même sens** que le mouvement, l'objet accélère. **En sens opposé**, il ralentit. **De côté** (perpendiculaire), il tourne sans changer d'allure.",
   "**Si on donne le mouvement** : construire $Δ@v{v}$, et conclure que la somme des forces pointe dans cette direction.",
   "**Pour un calcul de valeur**, avec une somme des forces supposée constante : $ΣF = m × @f{Δv}{Δt}$. D'abord $Δv$, la variation de vitesse en @u{m/s}. Puis $@f{Δv}{Δt}$, ce que la vitesse gagne **en une seconde**, en @u{m/s²}. Enfin, on multiplie par la masse."
  ], exemple:"Un chariot de $3{,}0$ @u{kg} passe de $2{,}0$ à $8{,}0$ @u{m/s} en $3{,}0$ @u{s}, poussé par une force constante. Sa vitesse a gagné $Δv = 8{,}0 - 2{,}0 = 6{,}0$ @u{m/s} en trois secondes, soit $@f{Δv}{Δt} = @f{6{,}0}{3{,}0} = 2{,}0$ @u{m/s} gagnés **chaque seconde**, ce qui s'écrit $2{,}0$ @u{m/s²}. Enfin $ΣF = 3{,}0 × 2{,}0 = 6{,}0$ @u{N}."}
 ]},

 {id:"s4", titre:"La chute libre : quand le poids agit seul", blocs:[
  {t:"idee", x:"Lâche une bille de plomb et une bille de plastique de la même hauteur : elles touchent le sol **ensemble**, ou presque : le petit écart vient de l'air, qui freine un peu plus la bille de plastique. C'est contraire à l'intuition — on croit spontanément que le plus lourd tombe plus vite — et c'est pourtant ce que dit la deuxième loi de Newton, comme on va le voir en deux lignes."},
  {t:"formule", titre:"Ce qu'on appelle une chute libre",
   x:"Un objet est en **chute libre** si le **poids est la seule force** qui s'exerce sur lui.",
   note:"En pratique : on néglige les frottements de l'air. C'est légitime pour une bille dense sur quelques mètres, faux pour une feuille de papier ou un parachute."},
  {t:"p", x:"La deuxième loi dit tout de suite ce qui se passe. La somme des forces, c'est le poids, toujours vertical vers le bas. Donc $Δ@v{v}$ pointe toujours **vers le bas**. Lâchée, la bille tombe de plus en plus vite. Lancée vers le haut, elle ralentit, s'arrête, puis redescend. Lancée de biais, sa trajectoire se courbe vers le sol : c'est la figure de la chute du chapitre précédent."},
  {t:"p", x:"Et la masse ? Voici les deux lignes annoncées. La deuxième loi dit que la variation de vitesse est d'autant plus grande que la force est grande, et d'autant plus petite que la masse est grande : $@f{Δ@v{v}}{Δt} = @f{Σ@v{F}}{m}$. En chute libre, la seule force est le poids, et le poids vaut $m@v{g}$. Comme il reste le même pendant toute la chute, la relation est ici exacte. On remplace :"},
  {t:"formule", titre:"La masse disparaît",
   x:"$@f{Δ@v{v}}{Δt} = @f{m@v{g}}{m} = @v{g}$",
   note:"$@v{g}$ est un vecteur vertical, vers le bas, de valeur $g$ : le poids s'écrit $@v{P} = m@v{g}$. Le $m$ du haut et le $m$ du bas se simplifient. La vitesse change donc de la même façon pour **tous** les objets, quelle que soit leur masse."},
  {t:"astuce", titre:"Pourquoi la masse s'en va", x:"Un objet deux fois plus lourd est attiré deux fois plus fort — mais il est aussi deux fois plus difficile à mettre en mouvement, comme le caddie plein. Les deux effets se compensent exactement, et il ne reste rien. C'est ce que Galilée avait compris avant Newton, et que l'équipage d'Apollo 15 a filmé sur la Lune en 1971 en lâchant ensemble un marteau et une plume : sans air, ils touchent le sol au même instant. Sur Terre, la plume arrive après à cause de l'air, pas parce qu'elle est légère."},
  {t:"formule", titre:"La même valeur, deux lectures",
   x:"$g = 9{,}81$ @u{N/kg} $= 9{,}81$ @u{m/s²}",
   note:"En @u{N/kg}, $g$ dit **la force** que subit chaque kilogramme. En @u{m/s²}, il dit **de combien la vitesse augmente** chaque seconde en chute libre : $9{,}81$ @u{m/s} de plus à chaque seconde. C'est le même nombre parce que $1$ @u{N} $= 1$ @u{kg·m/s²}, donc $1$ @u{N/kg} $= 1$ @u{m/s²}."},
  {t:"piege", titre:"La chute libre a ses limites", x:"Ce modèle suppose l'air négligeable. Dans la réalité, le frottement de l'air grandit avec la vitesse, jusqu'à égaler le poids. À partir de là, $Σ@v{F} = @v{0}$ et la vitesse ne change plus : ce n'est plus une chute libre, c'est la **vitesse limite** — environ $200$ @u{km/h} pour un parachutiste à plat, et $20$ @u{km/h} une fois le parachute ouvert. C'est le parachutiste de la section 2. Une goutte de pluie, elle, atteint sa vitesse limite en quelques mètres : sans l'air, en tombant d'un nuage, elle arriverait au sol à plusieurs centaines de @u{km/h}."},
  {t:"check", q:"Une balle lancée verticalement vers le haut atteint le sommet de sa trajectoire : à cet instant, sa vitesse est nulle. Que vaut la somme des forces à cet instant (air négligé) ?",
   choix:["Le poids, dirigé vers le bas","Elle est nulle, puisque la vitesse est nulle","Une force vers le haut, qui vient de s'épuiser","Elle change de sens à cet instant"], bonne:0,
   expl:["Exact. Le poids est la seule force, du début à la fin du vol, et il ne dépend pas de la vitesse. C'est lui qui a ralenti la montée, et c'est lui qui va faire redescendre la balle : sa vitesse est nulle, mais elle **change** encore.",
         "Une vitesse nulle ne veut pas dire que la vitesse ne change pas. Si la somme des forces était nulle au sommet, la balle y resterait suspendue, immobile. Elle redescend : son vecteur vitesse change, donc une force agit.",
         "Aucune force « d'élan » n'accompagne la balle : une fois lâchée, la main n'agit plus. Ce qui la fait monter, c'est sa vitesse de départ, pas une force.",
         "Le poids garde la même direction et le même sens pendant tout le vol. Ce qui change de sens au sommet, c'est le mouvement, pas la force."]}
 ]},

 {id:"s5", titre:"Deux forces à distance : gravitation et électrostatique", blocs:[
  {t:"p", x:"Certaines forces agissent **sans contact**. Tu en connais déjà une : le poids. Le poids n'est rien d'autre que l'attraction de la Terre sur un objet proche du sol. C'est un cas particulier d'une force bien plus générale, la **gravitation** : **deux objets qui ont une masse s'attirent toujours**. La Terre et toi, la Terre et la Lune, et même toi et ta voisine de table. Une seconde force à distance est au programme, la force électrique, et leurs formules se ressemblent de façon frappante."},
  {t:"p", x:"Deux idées suffisent à deviner la forme de la loi de gravitation. Si l'on double une des masses, c'est comme mettre deux objets côte à côte, chacun attiré autant : la force double. Elle est donc proportionnelle à chaque masse. Et plus on s'éloigne, plus l'attraction faiblit : Newton a montré, à partir du mouvement des planètes, qu'elle est divisée par le **carré** de la distance."},
  {t:"formule", titre:"Force d'interaction gravitationnelle",
   x:"$F = G × @f{m_A × m_B}{d^2}$",
   note:"$m_A$ et $m_B$ : les masses des deux objets, en @u{kg} · $d$ : la distance entre leurs **centres**, en @u{m} (pour la Terre, on compte depuis son centre, pas depuis le sol) · $G = 6{,}67 × 10^{-11}$ : un nombre fixe, le même partout dans l'Univers, mesuré une fois pour toutes. Son unité, @u{N·m²·kg⁻²}, n'est pas à retenir : elle sert seulement à ce que le résultat sorte en newtons. Cette force est toujours **attractive**."},
  {t:"p", x:"Pourquoi ne sens-tu pas ta voisine t'attirer ? À cause de $G$ : $10^{-11}$, c'est « 0, » suivi de dix zéros avant le premier chiffre. Deux élèves de $60$ @u{kg} à $1$ @u{m} l'une de l'autre s'attirent avec $6{,}67 × 10^{-11} × @f{60 × 60}{1^2} ≈ 2{,}4 × 10^{-7}$ @u{N}, à peu près le poids d'un grain de sable fin. Pour que la gravitation se fasse sentir, il faut au moins une masse gigantesque, comme celle d'une planète."},
  {t:"p", x:"La seconde force à distance concerne la **charge électrique**. Frotte une règle en plastique sur un pull, puis approche-la de petits bouts de papier : ils sautent vers elle, sans contact. La règle s'est **chargée**. Il existe deux sortes de charges, qu'on a appelées **positive** et **négative** : un proton porte $+1{,}6 × 10^{-19}$ @u{C}, un électron $-1{,}6 × 10^{-19}$ @u{C}. Deux charges de même signe se repoussent, deux charges de signes contraires s'attirent. Une charge se note $q$ et se mesure en **coulombs** (@u{C}). Le coulomb est une unité énorme à l'échelle d'un objet frotté : la règle porte une charge de l'ordre du nanocoulomb ($10^{-9}$ @u{C}). Un **microcoulomb** ($1$ @u{µC} $= 10^{-6}$ @u{C}, un millionième de coulomb) est déjà une charge importante. On retrouvera le coulomb au chapitre suivant, avec le courant électrique."},
  {t:"p", x:"La loi de la force électrique se devine de la même façon qu'avec les masses : doubler une des charges double la force, et la force est divisée par le carré de la distance."},
  {t:"formule", titre:"Force d'interaction électrostatique (loi de Coulomb)",
   x:"$F = k × @f{|q_A × q_B|}{d^2}$",
   note:"$q_A$ et $q_B$ : les deux charges, en @u{C} · $d$ : la distance entre elles, en @u{m} · $k = 9{,}0 × 10^{9}$ : là encore un nombre fixe, dont l'unité (@u{N·m²·C⁻²}) n'est pas à retenir. Les barres verticales $|…|$ désignent la **valeur absolue**, c'est-à-dire le nombre sans son signe : $|-6| = 6$. Elles sont là parce qu'une charge peut être négative, alors que la valeur d'une force est toujours positive. Le signe n'est pas perdu : il donne le **sens** de la force, attractive si les charges sont de signes contraires, répulsive si elles sont de même signe."},
  {t:"p", x:"Compare les deux forces pour deux protons, à n'importe quelle distance (elle se simplifie). La force électrique vaut $k × e^2$ divisé par $d^2$, la gravitation $G × m_p^2$ divisé par $d^2$, avec $e = 1{,}6 × 10^{-19}$ @u{C} et $m_p = 1{,}67 × 10^{-27}$ @u{kg}. Le rapport des deux vaut environ $10^{36}$ : la force électrique l'emporte de très, très loin. C'est pourquoi une règle frottée soulève un bout de papier alors que toute la Terre le tire vers le bas. (Le papier, lui, n'est pas chargé : la règle attire les charges qui sont en lui, un effet que tu n'as pas à connaître cette année.)"},
  {t:"p", x:"Les deux formules ont la même architecture : un produit des « quantités » en haut, le carré de la distance en bas. Cette dépendance en $@f{1}{d^2}$ a une conséquence marquante : **doubler la distance divise la force par quatre**, et non par deux. Tripler la distance la divise par neuf. Une image pour le sentir : une bombe de peinture tenue à $1$ @u{m} d'un mur fait une tache de $10$ @u{cm} de côté. Recule à $2$ @u{m} : la tache fait $20$ @u{cm} de côté, soit une surface quatre fois plus grande pour la même peinture. Chaque centimètre carré en reçoit quatre fois moins. L'influence d'une masse ou d'une charge s'étale de la même façon dans toutes les directions."},
  {t:"fig", titre:"Une force qui décroît en 1/d²",
   vue:[0,0,5.2,1.15], w:400, h:250, libre:true, grille:false, axes:false,
   objets:[
    {t:"axes", x0:0, y0:0, ax:"distance d", ay:"force F"},
    {t:"courbeXY", couleur:"bleu", point:{dur:"3s"},
     pts:[[0.5,1.0],[0.7,0.51],[0.9,0.31],[1.1,0.21],[1.4,0.13],[1.8,0.077],[2.3,0.047],[3,0.028],[4,0.016],[5,0.010]]},
    {t:"seg", de:[1,0], a:[1,0.25], couleur:"line2", pointille:true},
    {t:"seg", de:[2,0], a:[2,0.0625], couleur:"line2", pointille:true},
    {t:"texte", x:1.05, y:0.35, txt:"d", couleur:"ink3"},
    {t:"texte", x:2.15, y:0.16, txt:"2d → F ÷ 4", couleur:"rouge", taille:12}
   ],
   note:"La force diminue vite quand la distance augmente : divisée par $4$ à distance double, par $100$ à distance décuple. Mais elle ne s'annule jamais : c'est encore elle qui retient la Lune, à $380\u00a0000$ @u{km} de la Terre, parce que les masses en jeu sont gigantesques."},
  {t:"exemple", titre:"Exemple guidé — la force entre la Terre et la Lune", enonce:"Calculer la force gravitationnelle entre la Terre ($m_T = 6{,}0 × 10^{24}$ @u{kg}) et la Lune ($m_L = 7{,}3 × 10^{22}$ @u{kg}), distantes de $d = 3{,}8 × 10^{8}$ @u{m}.", etapes:[
   {q:"Écrire la formule", r:"$F = G × @f{m_T × m_L}{d^2}$, avec $G = 6{,}67 × 10^{-11}$ @u{N·m²·kg⁻²}."},
   {q:"Calculer le numérateur", r:"$m_T × m_L = 6{,}0 × 10^{24} × 7{,}3 × 10^{22}$. Je multiplie les nombres entre eux, $6{,}0 × 7{,}3 = 43{,}8$, et j'additionne les exposants, $24 + 22 = 46$. Cela donne $43{,}8 × 10^{46} = 4{,}38 × 10^{47}$ @u{kg²}. On garde au moins un chiffre de plus que les données dans les calculs intermédiaires, et on n'arrondit qu'à la fin."},
   {q:"Calculer le dénominateur", r:"$d^2 = (3{,}8 × 10^{8})^2$ : $3{,}8^2 = 14{,}44$ et $(10^{8})^2 = 10^{16}$, d'où $14{,}44 × 10^{16} = 1{,}444 × 10^{17}$ @u{m²}. Attention : le carré porte sur le nombre **et** sur la puissance de dix."},
   {q:"Assembler", r:"D'abord la fraction : $@f{4{,}38 × 10^{47}}{1{,}444 × 10^{17}} ≈ 3{,}03 × 10^{30}$ @u{kg²/m²} (on divise les nombres, on soustrait les exposants : $47 - 17 = 30$). Puis $F = 6{,}67 × 10^{-11} × 3{,}03 × 10^{30} ≈ 2{,}0 × 10^{20}$ @u{N}."},
   {q:"Interpréter", r:"Dans le référentiel géocentrique, c'est cette force qui courbe en permanence le vecteur vitesse de la Lune vers la Terre et la maintient sur son orbite. (Le Soleil attire aussi la Lune, et même plus fort que la Terre. Mais il fait varier la vitesse de la Terre presque exactement comme celle de la Lune, kilogramme pour kilogramme : vu depuis la Terre, dans le référentiel géocentrique, son effet se compense presque. On le néglige ici.)"}
  ]},
  {t:"piege", titre:"Le carré au dénominateur", x:"Une erreur très fréquente : oublier de mettre la distance **au carré**, ou n'élever au carré que le nombre sans la puissance de dix. $(3 × 10^{8})^2 = 9 × 10^{16}$, et non $3 × 10^{16}$ ni $9 × 10^{8}$."},
  {t:"p", x:"Retour au poids. Le poids d'un objet posé sur Terre n'est autre, à très peu près, que la force gravitationnelle exercée par la Terre, avec $d$ égal au rayon terrestre $R_T = 6{,}4 × 10^{6}$ @u{m} : $P = G @f{m_T × m}{R_T^2}$. Comme $P = m × g$, on en tire $g = G @f{m_T}{R_T^2} = 6{,}67 × 10^{-11} × @f{6{,}0 × 10^{24}}{(6{,}4 × 10^{6})^2} ≈ 9{,}8$ @u{N/kg}. On retrouve le $g$ du début du chapitre. Loin du sol, $d$ augmente et la Terre attire moins fort : c'est pourquoi un satellite en orbite subit une force plus faible que son poids au sol."}
 ]},

{id:"s6", titre:"Le principe des actions réciproques", blocs:[
  {t:"idee", x:"Une force n'existe jamais seule. Si un corps $@c{A}$ exerce une force sur un corps $@c{B}$, alors $@c{B}$ exerce **en même temps** sur $@c{A}$ une force de même valeur, de même direction, et de sens opposé. C'est la troisième loi de Newton."},
  {t:"p", x:"Deux patineuses face à face sur la glace : l'une pousse l'autre, et elles partent **toutes les deux** en arrière. Pourtant une seule a poussé. C'est que pousser, c'est aussi être poussé : le geste crée deux forces d'un coup, une sur chacune."},
  {t:"formule", titre:"Troisième loi de Newton",
   x:"$@v{F}_{A/B} = - @v{F}_{B/A}$",
   note:"Le signe $-$ devant un vecteur veut dire « la même flèche, retournée » : même longueur, même ligne, pointe de l'autre côté. Les deux forces sont portées par la même droite, celle qui relie les deux objets : c'est ce qu'on appelle leur **droite d'action**. Et surtout : les deux forces s'exercent sur **deux objets différents**."},
  {t:"fig", titre:"Deux forces, deux objets",
   vue:[0,0,10,5], w:430, h:200, grille:false, axes:false,
   objets:[
    {t:"sol", de:0.6, a:9.4, y:1.2},
    {t:"rect", x:2, y:1.2, w:1.6, h:1.6, couleur:"bleu"},
    {t:"rect", x:6.4, y:1.2, w:1.6, h:1.6, couleur:"vert"},
    {t:"texte", x:2.8, y:3.15, txt:"A", couleur:"bleu", taille:14},
    {t:"texte", x:7.2, y:3.15, txt:"B", couleur:"vert", taille:14},
    /* les deux flèches pulsent EN PHASE : l'action et la réaction naissent
       et existent au même instant, jamais l'une avant l'autre. */
    /* chaque flèche part du centre de l'objet qui SUBIT la force : A pousse
       B vers la droite, B repousse A vers la gauche (les patineuses) */
    {t:"vec", de:[7.2,2.0], a:[9.2,2.0], couleur:"rouge", anime:[{attr:"stroke-width", values:"2.4;3.8;2.4", dur:"1.3s"}]},
    {t:"vec", de:[2.8,2.0], a:[0.8,2.0], couleur:"ambre", anime:[{attr:"stroke-width", values:"2.4;3.8;2.4", dur:"1.3s"}]},
    {t:"texte", x:8.7, y:2.35, txt:"F A/B", couleur:"rouge", taille:12},
    {t:"texte", x:1.3, y:2.35, txt:"F B/A", couleur:"ambre", taille:12},
    {t:"texte", x:5, y:0.25, txt:"deux corps distincts, une force sur chacun", couleur:"ink3", taille:11.5}
   ],
   note:"La flèche rouge part de B : c'est une force subie par B. La flèche ambre part de A. Même longueur, sens opposés, et elles ne s'appliquent jamais au même objet."},
  {t:"piege", titre:"Ces deux forces ne se compensent jamais", x:"C'est **le** piège de la mécanique. Deux forces ne peuvent se compenser que si elles s'exercent sur le **même** objet. Ici, l'une agit sur $@c{A}$, l'autre sur $@c{B}$ : elles appartiennent à deux bilans de forces différents, et n'ont aucune raison de s'annuler. Si elles se compensaient, rien ne pourrait jamais bouger."},
  {t:"p", x:"À ne pas confondre, donc, avec le poids et la réaction du support d'un livre posé sur une table : ces deux-là s'exercent bien sur **le même** livre, et se compensent. Le partenaire du poids du livre, c'est l'attraction que le livre exerce sur la Terre — une force qu'on ne voit jamais dessinée, et qui existe pourtant."},
  {t:"methode", titre:"Repérer une paire action–réaction", etapes:[
   "**Nommer les deux corps en présence**, et rien qu'eux : le pied et le sol, la roue et la route, la Terre et la pomme.",
   "**Écrire la première force en citant les deux** : $@v{F}_{pied/sol}$. Le premier nom est celui qui agit, le second celui qui subit.",
   "**Écrire la réciproque en inversant les deux noms** : $@v{F}_{sol/pied}$. C'est elle, la partenaire — aucune autre.",
   "**Vérifier qu'elles s'appliquent à deux objets différents.** Si les deux flèches partent du même objet, ce n'est pas une paire action–réaction.",
   "**Ne jamais les mettre dans le même bilan de forces** : chacune appartient à celui de l'objet qu'elle subit."
  ], exemple:"Pour marcher, le pied pousse le sol vers l'**arrière** ; le sol pousse alors le pied vers l'**avant**. C'est cette seconde force, et elle seule, qui fait avancer le marcheur — le sol nous propulse."},
  {t:"check", q:"Un cheval tire une charrette. La charrette tire le cheval en arrière avec exactement la même force. Comment l'attelage peut-il avancer ?",
   choix:["Ces deux forces s'exercent sur des objets différents : elles n'appartiennent pas au même bilan",
          "La force du cheval est en réalité un peu plus grande",
          "La force de la charrette n'existe pas vraiment",
          "L'attelage n'avance que si le sol est glissant"], bonne:0,
   expl:["Exact : la force du cheval agit sur la charrette, celle de la charrette agit sur le cheval. Pour savoir si le cheval avance, on ne regarde que le bilan **du cheval** — où figure aussi la poussée du sol sur ses sabots.",
         "Non : la troisième loi est une égalité exacte, sans exception. Ce n'est pas là qu'il faut chercher.",
         "Elle existe bel et bien, et le cheval la sent dans ses harnais. Elle ne s'applique simplement pas au même objet.",
         "C'est l'inverse : sans adhérence, le cheval patine sur place. C'est justement le sol qui, en le poussant vers l'avant, permet le mouvement."]}
 ]},
 {id:"s7", titre:"Atelier — de la somme des forces au mouvement", blocs:[
  {t:"p", x:"Un exercice de mécanique se déroule presque toujours dans le même ordre : le bilan des forces, la somme, puis la conclusion sur le mouvement. Cet atelier te fait parcourir cet ordre une fois en entier, en calculant chaque valeur toi-même."},
  {t:"atelier", titre:"Une luge tirée sur la neige",
   enonce:"Une luge de $20$ @u{kg} est tirée horizontalement par une corde qui exerce une force $F = 60$ @u{N}. La neige exerce sur elle une force de frottement $f = 20$ @u{N}, opposée au mouvement. On prend $g = 9{,}81$ @u{N/kg}.",
   etapes:[
    {q:"Première force du bilan : quelle est la valeur du poids de la luge, en @u{N} ? (donne le résultat au dixième)",
     rep:196.2, tol:1, unite:"N",
     aide:"Le poids est le produit de la masse par l'intensité de la pesanteur.",
     diag:[{v:20, m:"$20$ @u{kg} est la **masse**, en kilogrammes. Le poids est une force, en newtons : il vaut $m × g$."},
           {v:2.04, m:"Tu as divisé la masse par $g$. C'est une multiplication : $P = m g$."},
           {v:200, m:"Presque : avec $g = 10$ on trouverait $200$ @u{N}. L'énoncé impose $9{,}81$, donc $196{,}2$ @u{N}."}],
     expl:"$P = m × g = 20 × 9{,}81 = 196{,}2$ @u{N}. **Masse et poids ne sont pas la même chose.** La masse caractérise la luge elle-même : elle vaut $20$ @u{kg} ici, sur la Lune et dans l'espace. Le poids est la force que la Terre exerce sur elle : il change d'un astre à l'autre. Sur la Lune, cette même luge pèserait environ $32$ @u{N}."},

    {q:"La luge glisse sur la neige sans s'enfoncer ni décoller. Que vaut alors la force exercée par le sol sur elle, en @u{N} ?",
     rep:196.2, tol:1, unite:"N",
     aide:"Verticalement, rien ne change dans le mouvement. Que doit valoir la somme des forces verticales ?",
     diag:[{v:0, m:"Si le sol n'exerçait aucune force, plus rien ne retiendrait la luge et elle s'enfoncerait. Il pousse bien vers le haut."},
           {v:392.4, m:"Tu as doublé le poids. La réaction le **compense** exactement : elle a la même valeur, pas le double."},
           {v:60, m:"$60$ @u{N} est la force de traction, qui est horizontale. La réaction du sol est verticale."}],
     expl:"La réaction du sol vaut $196{,}2$ @u{N}, dirigée vers le haut. **Le raisonnement, et il faut le savoir refaire.** La luge ne s'enfonce pas et ne décolle pas : verticalement, son mouvement ne change pas. D'après le principe d'inertie, la somme des forces verticales est donc nulle — et comme il n'y en a que deux, elles se compensent. Ce n'est pas une formule à retenir, c'est une déduction en trois phrases, à refaire à chaque fois."},

    {q:"Passe à l'horizontale : quelle est la valeur de la somme des forces horizontales, en @u{N} ?",
     rep:40, tol:0.5, unite:"N",
     aide:"Les deux forces horizontales sont de sens opposés. Que fait-on de deux flèches opposées ?",
     diag:[{v:80, m:"Tu as additionné $60$ et $20$. Ces deux forces sont de sens **opposés** : elles se retranchent."},
           {v:0, m:"Elles ne se compensent pas : $60$ @u{N} et $20$ @u{N} n'ont pas la même valeur."},
           {v:1200, m:"Tu as multiplié les deux forces. Une somme de forces ne se multiplie jamais."}],
     expl:"$60 - 20 = 40$ @u{N}, dirigés dans le sens du mouvement. **Pourquoi une soustraction.** Additionner des forces, c'est mettre les flèches bout à bout. Quand elles pointent en sens contraire, l'une annule une partie de l'autre : il ne reste que la différence, orientée du côté de la plus grande. On dit que la somme est de $40$ @u{N} « vers l'avant » — la direction fait partie de la réponse."},

    {q:"Que vaut alors la somme de **toutes** les forces qui s'exercent sur la luge ?",
     choix:["$40$ @u{N}, dirigés dans le sens du mouvement","$0$ @u{N}, tout se compense","$236{,}2$ @u{N}, en additionnant tout","$196{,}2$ @u{N}, comme le poids"],
     bonne:0,
     diag:["","Les forces **verticales** se compensent, mais pas les horizontales : il reste $40$ @u{N}.",
           "On n'additionne pas des forces de directions différentes comme des nombres. La verticale et l'horizontale se traitent séparément.",
           "Le poids est compensé par la réaction du sol : ces deux-là ne contribuent plus à la somme."],
     expl:"La somme totale vaut $40$ @u{N}, horizontaux, dirigés vers l'avant. **La méthode en une phrase.** On traite la verticale d'un côté — ici tout se compense, il ne reste rien — et l'horizontale de l'autre — il reste $40$ @u{N}. La somme totale est ce qui subsiste, et rien d'autre. Le poids et la réaction ont bel et bien agi : simplement, ils se sont annulés."},

    {q:"Dernière étape, la conclusion. Que fait la luge ?",
     choix:["Sa vitesse augmente, dans le sens du mouvement","Elle avance à vitesse constante","Elle ralentit puis s'arrête","On ne peut pas conclure sans connaître sa vitesse actuelle"],
     bonne:0,
     diag:["","À vitesse constante, la somme des forces serait nulle. Ici il reste $40$ @u{N} : quelque chose doit changer.",
           "Elle ralentirait si la somme des forces pointait vers l'arrière. Ici elle pointe vers l'avant, du côté de la traction.",
           "C'est justement la force des lois de Newton : la vitesse **actuelle** n'entre pas en jeu. Seule compte la façon dont elle va **changer**."],
     expl:"La vitesse augmente, dans le sens de la somme des forces. **Le point le plus important du chapitre.** La deuxième loi ne dit pas où va la luge ni à quelle vitesse : elle dit **comment la vitesse change**. Une somme de forces non nulle vers l'avant signifie une vitesse qui augmente — que la luge soit déjà lancée ou à l'arrêt. Si le frottement montait à $60$ @u{N}, la somme deviendrait nulle et la luge continuerait à la vitesse qu'elle a, sans accélérer ni ralentir."}
   ],
   bilan:"Les trois temps d'un exercice de mécanique, dans l'ordre : **le bilan** (quelles forces, sur quel objet), **la somme** (verticale d'abord, horizontale ensuite, jamais mélangées), **la conclusion** (ce que devient la vitesse, pas où va l'objet). Cet ordre marche pour toute la mécanique de Première."}
 ]},

 {id:"s8", titre:"Récapitulatif : la méthode d'un exercice de mécanique", blocs:[
  {t:"liste", items:[
   "**1.** Choisir le système étudié (l'objet dont on parle) et le référentiel (ce par rapport à quoi on décrit son mouvement ; en général le sol, le « référentiel terrestre »).",
   "**2.** Faire l'inventaire des forces : qui agit sur ce système ? Contact ou distance ?",
   "**3.** Les représenter par des vecteurs, à partir du centre de l'objet.",
   "**4.** Regarder si elles se compensent. Si oui, le vecteur vitesse ne change pas.",
   "**5.** Si non, la somme donne la direction et le sens de $Δ@v{v}$ — donc l'évolution du mouvement."
  ]},
  {t:"tbl", head:["La question ressemble à…","Ce qu'il faut faire"], rows:[
   ["« Calculer $ΣF$ à partir d'un changement de vitesse »","$ΣF ≈ m × @f{Δv}{Δt}$ : d'abord $Δv$, puis par seconde, puis $× m$"],
   ["« Deux objets lâchés ensemble »","En chute libre, la masse se simplifie : ils arrivent ensemble"],
   ["« Calculer le poids »","$P = m × g$, la masse en @u{kg}"],
   ["« Le mouvement est rectiligne uniforme »","Conclure $Σ@v{F} = @v{0}$"],
   ["« Vers où pointe $Δ@v{v}$ ? »","Vers la somme des forces"],
   ["« Force gravitationnelle »","$G @f{m_A m_B}{d^2}$, distance **au carré**"],
   ["« Si la distance double »","La force est divisée par $4$"]
  ]},
  {t:"piege", titre:"Les erreurs les plus coûteuses", x:"**1.** Confondre masse ($@u{kg}$) et poids ($@u{N}$).<br>**2.** Croire que la force indique la direction du **mouvement** ; elle indique celle de son **changement**.<br>**3.** Oublier le carré de la distance dans les forces à distance."}
 ]}
],
exos:[
 {id:"fo1", niveau:1, type:"num", enonce:"Quelle est la valeur du poids d'un sac de $4{,}0$ @u{kg} sur Terre ? On prend $g = 9{,}81$ @u{N/kg}.",
  rep:39.24, tol:0.3, unite:"N",
  diag:[{v:4, m:"Tu as recopié la masse. La masse s'exprime en @u{kg}, le poids en @u{N} : ce sont deux grandeurs différentes, reliées par $P = m × g$."},
        {v:0.41, m:"Tu as divisé la masse par $g$ au lieu de multiplier. Le poids est plus grand que la masse en valeur numérique, puisque $g ≈ 10$."},
        {v:2.45, m:"Tu as calculé $@f{g}{m}$. La formule est $P = m × g$."}],
  corr:["**Ce que dit l'énoncé.** Une masse $m = 4{,}0$ @u{kg}, et $g = 9{,}81$ @u{N/kg}. On cherche la valeur du poids.",
        "**La différence à ne pas confondre.** La masse caractérise l'objet, en @u{kg} : elle ne dépend pas de l'endroit où il se trouve. Le poids est une **force**, en @u{N} : c'est l'attraction exercée par l'astre, et elle dépend de l'astre.",
        "**La formule qui relie les deux.** $P = m × g$, où $g$ vaut $9{,}81$ @u{N/kg} sur Terre : chaque kilogramme y est tiré avec une force d'environ $9{,}81$ @u{N}.",
        "**Je remplace.** $P = 4{,}0 × 9{,}81$.",
        "**Je calcule.** $P = 39{,}24 ≈ 39$ @u{N}, avec deux chiffres significatifs comme la masse.",
        "**Je vérifie de tête.** Environ $10$ @u{N} par kilogramme : quatre kilos donnent à peu près $40$ @u{N}. Cohérent, et l'unité est bien le newton."],
  indice:"$P = m × g$, avec $g ≈ 9{,}81$ @u{N/kg}."},

 {id:"fo2", niveau:1, type:"qcm", enonce:"Un palet glisse en ligne droite à vitesse constante sur une patinoire. Que vaut la somme des forces qui s'exercent sur lui ?",
  choix:["Le vecteur nul","Un vecteur dirigé vers l'avant","Son poids","Un vecteur dirigé vers l'arrière"], bonne:0,
  diag:["",
        "Une force vers l'avant le ferait **accélérer**. Or sa vitesse ne change pas.",
        "Le poids s'exerce bien, mais la glace le compense exactement par sa réaction. C'est la **somme** qui est nulle, pas chaque force.",
        "Une force vers l'arrière le ferait ralentir. C'est ce qui arrive en réalité avec les frottements — mais l'énoncé précise une vitesse constante."],
  corr:["**Ce que dit l'énoncé.** Un palet glisse **en ligne droite à vitesse constante** sur une patinoire. On cherche la somme des forces.",
        "**Je traduis l'énoncé en termes de vecteur vitesse.** Ligne droite = direction constante. Vitesse constante = valeur constante. Le vecteur vitesse ne change donc pas du tout.",
        "**J'en déduis sa variation.** $Δ@v{v} = @v{0}$.",
        "**J'applique le principe d'inertie.** Si le vecteur vitesse ne change pas, la somme des forces est nulle. Et réciproquement.",
        "**Je conclus.** $Σ@v{F} = @v{0}$.",
        "**Attention à ne pas surinterpréter.** Cela ne signifie pas qu'aucune force n'agit : le poids tire vers le bas, la glace pousse vers le haut. C'est leur **somme** qui est nulle, parce qu'elles se compensent exactement."],
  indice:"Principe d'inertie : vitesse constante en ligne droite signifie forces compensées."},

 {id:"fo3", niveau:2, type:"qcm", enonce:"Une balle est lancée verticalement vers le haut. Pendant sa montée, quelle est la direction de la somme des forces (on néglige l'air) ?",
  choix:["Vers le bas","Vers le haut, comme le mouvement","Nulle, car elle monte à vitesse constante","Elle change de sens au sommet"], bonne:0,
  diag:["",
        "C'est l'erreur la plus répandue en mécanique. La force n'indique pas le sens du **mouvement**, mais celui de son **changement**. La balle monte tout en ralentissant : la force est donc dirigée vers le bas.",
        "La balle ralentit pendant sa montée : sa vitesse n'est pas constante. La somme des forces n'est donc pas nulle.",
        "Le poids garde exactement la même direction et le même sens pendant tout le trajet, montée comprise. Rien ne change au sommet, sinon le sens du mouvement."],
  corr:["**Ce que dit l'énoncé.** Une balle est lancée verticalement vers le haut, l'air est négligé. On cherche la direction de la somme des forces **pendant la montée**.",
        "**Étape 1 — l'inventaire des forces.** Une fois la balle lâchée, la main n'agit plus. L'air est négligé. Il ne reste que le **poids**.",
        "**Étape 2 — la direction du poids.** Verticale, vers le bas. Toujours, partout, pendant tout le vol : à la montée, au sommet, à la descente.",
        "**Étape 3 — le piège à éviter.** La deuxième loi ne dit pas que la force donne la direction du **mouvement**, mais celle de son **changement**. La balle monte tout en ralentissant.",
        "**Étape 4 — je vérifie la cohérence.** Une force opposée au mouvement freine : c'est bien ce qu'on observe, la balle ralentit jusqu'à s'arrêter.",
        "**Je conclus.** La somme des forces est dirigée **vers le bas**, pendant toute la montée. Au sommet la vitesse s'annule, puis le poids — inchangé — fait redescendre la balle en l'accélérant."],
  indice:"Sépare bien le sens du mouvement et le sens de son changement."},

 {id:"fo4", niveau:2, type:"num", enonce:"Sur la Lune, $g_L = 1{,}6$ @u{N/kg}. Quel est le poids d'une combinaison de $12$ @u{kg} sur la Lune ?",
  rep:19.2, tol:0.2, unite:"N",
  diag:[{v:117.7, m:"Tu as utilisé le $g$ terrestre ($9{,}81$). L'énoncé donne celui de la Lune : $1{,}6$ @u{N/kg}."},
        {v:12, m:"Tu as recopié la masse. La masse est la même partout ; c'est le poids qui change d'un astre à l'autre."},
        {v:7.5, m:"Tu as divisé la masse par $g_L$ au lieu de multiplier."}],
  corr:["**Ce que dit l'énoncé.** Une combinaison de $12$ @u{kg}, sur la Lune où $g_L = 1{,}6$ @u{N/kg}.",
        "**Ce qui change d'un astre à l'autre.** La masse ne change pas : $12$ @u{kg} sur Terre, $12$ @u{kg} sur la Lune. C'est $g$ qui change, parce que la Lune est bien moins massive que la Terre.",
        "**La formule reste la même.** $P = m × g$, avec le $g$ de l'astre concerné.",
        "**Je remplace avec le bon $g$.** $P = 12 × 1{,}6$.",
        "**Je calcule.** $P = 19{,}2 ≈ 19$ @u{N}, avec deux chiffres significatifs comme les données.",
        "**Je compare avec la Terre.** Sur Terre, la même combinaison pèserait $12 × 9{,}81 ≈ 118$ @u{N}, soit six fois plus. C'est exactement pour cela que les astronautes s'y déplacent par bonds — sans que leur masse ait changé d'un gramme."],
  indice:"Même formule, mais avec le $g$ de l'astre concerné."},

 {id:"fo5", niveau:2, type:"qcm", enonce:"Si la distance entre deux corps est multipliée par 3, par combien la force gravitationnelle est-elle divisée ?",
  choix:["9","3","6","27"], bonne:0,
  diag:["",
        "La distance intervient **au carré** au dénominateur. Une distance triplée donne donc $3^2 = 9$ au dénominateur, pas 3.",
        "6 correspondrait à $3 × 2$, un raisonnement qui mélange le facteur et l'exposant. Le carré de 3 vaut 9.",
        "27 serait le cube de 3. La loi de gravitation fait intervenir le carré de la distance, pas son cube."],
  corr:["**Ce que dit l'énoncé.** La distance entre deux corps est multipliée par $3$. On cherche par combien la force gravitationnelle est divisée.",
        "**J'écris la loi.** $F = G × @f{m_A m_B}{d^2}$. Les masses ne changent pas ; seule la distance varie.",
        "**Où se trouve la distance ?** Au **dénominateur**, et **au carré**. C'est ce carré qui fait toute la réponse.",
        "**J'applique le facteur.** Si $d$ devient $3d$, alors $d^2$ devient $(3d)^2 = 9 d^2$. Le dénominateur est multiplié par $9$, pas par $3$.",
        "**J'en déduis la force.** Un dénominateur $9$ fois plus grand donne une force $9$ fois plus petite.",
        "**Je conclus, et je retiens la règle.** La force est divisée par $9$. Doubler la distance divise par $4$, la tripler divise par $9$ : la force diminue vite avec la distance, sans jamais devenir nulle."],
  indice:"La distance est au carré : un facteur 3 sur $d$ devient un facteur $3^2$ sur $d^2$."},

 {id:"fo6", niveau:3, type:"num", enonce:"Deux charges de $q_A = 2{,}0 × 10^{-6}$ @u{C} et $q_B = 3{,}0 × 10^{-6}$ @u{C} sont distantes de $d = 0{,}30$ @u{m}. Quelle est la valeur de la force électrostatique, en @u{N} ? On prend $k = 9{,}0 × 10^{9}$ @u{N·m²·C⁻²}.",
  rep:0.6, tol:0.01, unite:"N",
  diag:[{v:0.18, m:"Tu as divisé par $d = 0{,}30$ @u{m} au lieu de $d^2 = 0{,}090$ @u{m²}. Comme $d$ est plus petit que $1$ @u{m}, son carré est encore plus petit que lui : oublier le carré donne ici une force trop **faible**."},
        {v:0.054, m:"Tu as calculé $k × q_A × q_B = 0{,}054$ @u{N·m²} sans diviser par $d^2$. La distance est au **dénominateur** : il reste à diviser par $0{,}30^2 = 0{,}090$ @u{m²}."},
        {v:6, m:"Une erreur d'un facteur 10 s'est glissée dans les puissances de dix. Reprends : $2{,}0×10^{-6} × 3{,}0×10^{-6} = 6{,}0×10^{-12}$ @u{C²}."}],
  corr:["**Ce que dit l'énoncé.** Deux charges, $q_A = 2{,}0 × 10^{-6}$ @u{C} et $q_B = 3{,}0 × 10^{-6}$ @u{C}, distantes de $d = 0{,}30$ @u{m}, avec $k = 9{,}0 × 10^{9}$.",
        "**La loi à utiliser.** La loi de Coulomb : $F = k × @f{|q_A × q_B|}{d^2}$. Même architecture que la gravitation : un produit en haut, le carré de la distance en bas.",
        "**Étape 1 — le numérateur.** $q_A × q_B = 2{,}0×10^{-6} × 3{,}0×10^{-6}$. Je multiplie les nombres : $2 × 3 = 6$. J'additionne les exposants : $-6 + (-6) = -12$. Donc $6{,}0 × 10^{-12}$ @u{C²}.",
        "**Étape 2 — le dénominateur.** $d^2 = 0{,}30^2 = 0{,}090$ @u{m²}. Attention : $0{,}30$ au carré ne fait pas $0{,}60$ mais $0{,}09$.",
        "**Étape 3 — j'assemble.** Je multiplie d'abord $k$ par le numérateur : $9{,}0×10^{9} × 6{,}0×10^{-12} = 54 × 10^{-3} = 0{,}054$ @u{N·m²}. Puis je divise par $d^2$ : $F = @f{0{,}054}{0{,}090} = 0{,}60$ @u{N}.",
        "**Je vérifie.** Moins d'un newton pour des charges de quelques microcoulombs (un microcoulomb vaut $10^{-6}$ @u{C}) à $30$ @u{cm} : plausible. Oublier le carré aurait donné $0{,}18$ @u{N}, plus de trois fois **trop peu** : diviser par $0{,}30$ au lieu de $0{,}090$, c'est diviser par un nombre plus grand."],
  indice:"N'oublie pas d'élever la distance au carré avant de diviser."},

 {id:"fo7", niveau:3, type:"txt", enonce:"Une bille tourne à vitesse constante au bout d'une ficelle. Vers où pointe la somme des forces ? (quelques mots)",
  reps:["centre","interieur","main"],
  diag:[{r:"avant", m:"Vers l'avant, la bille irait de plus en plus vite. Or sa vitesse garde la même valeur : ce qui change, c'est sa direction."},
        {r:"exterieur", m:"Si la somme des forces pointait vers l'extérieur, la bille s'éloignerait et quitterait le cercle. C'est la ficelle qui la retient — donc qui tire vers l'intérieur."},
        {r:"nulle", m:"Si elle était nulle, la bille irait en ligne droite d'après le principe d'inertie. Or sa trajectoire est un cercle : quelque chose la fait tourner en permanence."}],
  corr:["**Ce que dit l'énoncé.** Une bille tourne à vitesse constante au bout d'une ficelle. On cherche la direction de la somme des forces.",
        "**Le raisonnement à suivre.** Je ne connais pas les forces, mais je connais le mouvement. Je lis donc la deuxième loi **à l'envers** : du mouvement vers les forces.",
        "**Étape 1 — le vecteur vitesse change-t-il ?** Sa valeur, non. Sa direction, oui : elle tourne en permanence pour rester tangente au cercle. Donc le vecteur change, et $Δ@v{v}$ n'est pas nul.",
        "**Étape 2 — je construis $Δ@v{v}$.** Deux vecteurs de même longueur, légèrement pivotés, reportés d'un même point : la flèche qui joint leurs pointes est dirigée vers l'intérieur du cercle.",
        "**Étape 3 — j'applique la deuxième loi.** $Σ@v{F}$ a la même direction et le même sens que $Δ@v{v}$ : elle pointe **vers le centre**.",
        "**Je vérifie physiquement.** C'est la ficelle qui tire la bille vers la main. Si on la coupe, plus rien ne la retient : elle part en ligne droite, selon la tangente. Ce qui confirme que la force allait bien vers le centre."],
  indice:"Construis $Δ@v{v}$ : la somme des forces pointe dans la même direction."},

 {id:"fo8", niveau:3, type:"num", enonce:"Un chariot de masse $m = 2{,}0$ @u{kg} voit sa vitesse passer de $1{,}0$ à $5{,}0$ @u{m/s} en $2{,}0$ @u{s}, en ligne droite. On suppose la somme des forces constante pendant ces $2{,}0$ @u{s}. Quelle est la valeur de la somme des forces, en @u{N} ?",
  rep:4, tol:0.05, unite:"N",
  diag:[{v:2, m:"Tu as calculé la variation de vitesse par seconde ($2{,}0$ @u{m/s²}) mais oublié de multiplier par la masse. La loi est $ΣF = m × @f{Δv}{Δt}$."},
        {v:8, m:"Tu as multiplié par la variation totale de vitesse sans diviser par la durée : $2{,}0 × 4{,}0 = 8{,}0$ @u{N}. La durée de $2{,}0$ @u{s} doit intervenir."},
        {v:5, m:"Tu as utilisé la vitesse finale au lieu de sa variation : $2{,}0 × @f{5{,}0}{2{,}0} = 5{,}0$ @u{N}. C'est le **changement** de vitesse qui compte, $Δv = 5{,}0 - 1{,}0 = 4{,}0$ @u{m/s}, pas sa valeur finale."}],
  corr:["**Ce que dit l'énoncé.** $m = 2{,}0$ @u{kg}, vitesse de $1{,}0$ à $5{,}0$ @u{m/s} en $2{,}0$ @u{s}, en ligne droite.",
        "**La loi à utiliser.** La deuxième loi de Newton, sous sa forme chiffrée : $ΣF = m × @f{Δv}{Δt}$.",
        "**Étape 1 — la variation de vitesse.** $Δv = 5{,}0 - 1{,}0 = 4{,}0$ @u{m/s}. C'est un **écart**, pas la vitesse finale.",
        "**Étape 2 — la variation par seconde.** $@f{Δv}{Δt} = @f{4{,}0}{2{,}0} = 2{,}0$ @u{m/s²}. La vitesse gagne $2$ @u{m/s} chaque seconde.",
        "**Étape 3 — je multiplie par la masse.** $ΣF = 2{,}0 × 2{,}0 = 4{,}0$ @u{N}.",
        "**Je vérifie le rôle de la masse.** À variation de vitesse égale, un chariot deux fois plus lourd demanderait une force deux fois plus grande. C'est bien ce que dit la formule : la masse mesure la résistance au changement de mouvement."],
  indice:"Trois temps : la variation de vitesse, sa valeur par seconde, puis la multiplication par la masse."},

{id:"fo9", niveau:1, type:"qcm", enonce:"Parmi ces forces, laquelle n'est **pas** une force de contact ?",
  choix:["Le poids","La tension d'un fil","La réaction du sol","Le frottement de l'air"], bonne:0,
  diag:["",
        "Un fil doit être attaché à l'objet pour le tirer : il y a bien contact.",
        "Le sol doit toucher l'objet pour le porter : c'est une force de contact.",
        "L'air touche l'objet en mouvement sur toute sa surface : c'est un contact, même s'il est diffus."],
  corr:["**La distinction à faire.** Une force de **contact** exige que les deux corps se touchent. Une force **à distance** agit à travers le vide.",
        "**Je teste la tension d'un fil.** Sans fil attaché, pas de tension : c'est un contact.",
        "**Je teste la réaction du sol.** Elle n'existe que si l'objet repose sur le sol : contact.",
        "**Je teste le frottement de l'air.** L'air frotte la surface de l'objet : contact également, même si l'on n'y pense pas toujours.",
        "**Je teste le poids.** La Terre attire la pomme sans la toucher, à travers des kilomètres d'air ou même de vide.",
        "**Je conclus.** Le poids est une force **à distance**, comme la gravitation et l'attraction électrique. C'est la seule de la liste."],
  indice:"Demande-toi, pour chacune : les deux corps ont-ils besoin de se toucher ?"},

 {id:"fo10", niveau:2, type:"num", enonce:"Un rover de masse $350$ @u{kg} est posé sur Mars, où $g_M = 3{,}7$ @u{N/kg}. Quelle est la valeur de son poids, en @u{N} ?",
  rep:1295, tol:5, unite:"N",
  diag:[{v:3434, m:"Tu as utilisé le $g$ terrestre ($9{,}81$). Sur Mars, il ne vaut que $3{,}7$ @u{N/kg} : la planète est bien moins massive."},
        {v:350, m:"Tu as recopié la masse. Elle est la même partout dans l'univers ; c'est le poids qui change d'un astre à l'autre."},
        {v:94.6, m:"Tu as divisé la masse par $g$ au lieu de multiplier."}],
  corr:["**Ce que dit l'énoncé.** Une masse en kilogrammes, et l'intensité de la pesanteur **sur Mars**.",
        "**La formule.** $P = m × g$, avec le $g$ de l'astre où se trouve l'objet.",
        "**Ce qui change, ce qui ne change pas.** La masse du rover est la même sur Terre et sur Mars : $350$ @u{kg}. Seul $g$ change.",
        "**Je remplace.** $P = 350 × 3{,}7$.",
        "**Je calcule.** $P = 1295 ≈ 1{,}3 × 10^{3}$ @u{N}, avec deux chiffres significatifs comme $g_M$.",
        "**Je compare.** Sur Terre, le même rover pèserait $350 × 9{,}81 ≈ 3434$ @u{N}, soit presque trois fois plus. C'est pourquoi un engin conçu pour Mars peut être plus léger — mais sa masse, elle, reste à transporter jusque là-bas."],
  indice:"$P = m × g$, avec le $g$ de Mars et non celui de la Terre."},

 {id:"fo11", niveau:2, type:"num", enonce:"Deux charges exercent l'une sur l'autre une force de $0{,}60$ @u{N}. On **double** la distance qui les sépare, sans rien changer d'autre. Que vaut la nouvelle force, en @u{N} ?",
  rep:0.15, tol:0.005, unite:"N",
  diag:[{v:0.3, m:"Tu as divisé par $2$. Mais la distance intervient **au carré** : doubler $d$ multiplie $d^2$ par $4$, donc divise la force par $4$."},
        {v:1.2, m:"Tu as multiplié par $2$. Éloigner les charges **diminue** la force, cela ne l'augmente pas."},
        {v:2.4, m:"Tu as multiplié par $4$ au lieu de diviser. La distance est au **dénominateur** : plus elle est grande, plus la force est faible."}],
  corr:["**La loi en jeu.** La loi de Coulomb : $F = k @f{|q_A q_B|}{d^2}$. Les charges ne changent pas, seule la distance varie.",
        "**Où se trouve la distance.** Au dénominateur, et **au carré**. C'est ce carré qui fait toute la réponse.",
        "**J'applique le facteur.** Si $d$ devient $2d$, alors $d^2$ devient $(2d)^2 = 4 d^2$.",
        "**J'en déduis l'effet sur la force.** Un dénominateur $4$ fois plus grand donne une force $4$ fois plus petite.",
        "**Je calcule.** $F = @f{0{,}60}{4} = 0{,}15$ @u{N}.",
        "**La règle à retenir.** Distance $×2$ → force $÷4$. Distance $×3$ → force $÷9$. La force diminue vite quand on éloigne les charges, mais elle ne s'annule jamais."],
  indice:"Doubler la distance ne divise pas la force par 2 : regarde la puissance à laquelle $d$ apparaît."},

 {id:"fo12", niveau:3, type:"num", enonce:"Un satellite de masse $m_s = 800$ @u{kg} orbite à $7{,}0 × 10^{6}$ @u{m} du centre de la Terre ($m_T = 6{,}0 × 10^{24}$ @u{kg}). Quelle est la valeur de la force gravitationnelle, en @u{N} ? On donne $G = 6{,}67 × 10^{-11}$ @u{N·m²·kg⁻²}.",
  rep:6534, tol:80, unite:"N",
  diag:[{v:4.57e10, m:"Tu as oublié d'élever la distance au carré : tu as divisé par $7{,}0 × 10^{6}$ @u{m} au lieu de $4{,}9 × 10^{13}$ @u{m²}. Résultat : environ $4{,}6 × 10^{10}$ @u{N}, sept millions de fois trop."},
        {v:7848, m:"Tu as calculé le poids au sol ($800 × 9{,}81$). À $7000$ @u{km} du centre, la Terre attire moins fort."},
        {v:800, m:"Tu as recopié la masse du satellite. La question porte sur une force, en newtons."}],
  corr:["**La loi en jeu.** $F = G × @f{m_T × m_s}{d^2}$, avec les masses en @u{kg} et la distance en @u{m} : ce sont les unités dans lesquelles $G$ est donné.",
        "**Le numérateur, étape par étape.** $m_T × m_s = 6{,}0 × 10^{24} × 800 = 4{,}8 × 10^{27}$ @u{kg²}.",
        "**Je multiplie par $G$.** $6{,}67 × 10^{-11} × 4{,}8 × 10^{27} = 3{,}20 × 10^{17}$ @u{N·m²}. J'additionne les exposants : $-11 + 27 = 16$, et $6{,}67 × 4{,}8 = 32$, soit $32 × 10^{16} = 3{,}20 × 10^{17}$.",
        "**Le dénominateur.** $d^2 = (7{,}0 × 10^{6})^2 = 49 × 10^{12} = 4{,}9 × 10^{13}$ @u{m²}. Le carré porte sur le nombre **et** sur la puissance de dix.",
        "**Je divise.** $F = @f{3{,}20 × 10^{17}}{4{,}9 × 10^{13}} ≈ 6{,}5 × 10^{3}$ @u{N}.",
        "**J'interprète.** Environ $6500$ @u{N}, contre $7848$ @u{N} pour le même satellite posé au sol : plus loin du centre, la Terre attire moins fort. Dans le référentiel géocentrique, c'est cette force qui courbe en permanence la trajectoire du satellite et le maintient en orbite au lieu de le laisser filer tout droit."],
  indice:"Traite le numérateur et le dénominateur séparément, et n'oublie pas le carré sur la puissance de dix."},

{id:"fo13", niveau:2, type:"qcm", enonce:"Un livre est posé sur une table. Quelle est la force **réciproque** du poids du livre ?",
  choix:["L'attraction que le livre exerce sur la Terre",
         "La réaction de la table sur le livre",
         "Le poids de la table",
         "La force de frottement entre le livre et la table"], bonne:0,
  diag:["",
        "C'est la confusion la plus fréquente. La réaction de la table s'exerce sur le **même** objet que le poids — le livre — et c'est pour cela qu'elles se compensent. Une paire action–réaction, elle, se répartit sur deux objets.",
        "Le poids de la table est l'attraction exercée par la Terre sur la table : une autre force, qui concerne un autre objet.",
        "Le frottement s'exerce lui aussi sur le livre, et il est horizontal. Rien à voir avec le poids."],
  corr:["**Ce que dit l'énoncé.** Le poids du livre, c'est-à-dire la force exercée par la **Terre** sur le **livre**.",
        "**La règle de la troisième loi.** La force réciproque s'obtient en **inversant les deux noms** : si la Terre agit sur le livre, alors le livre agit sur la Terre.",
        "**J'écris la paire.** $@v{F}_{Terre/livre}$ et $@v{F}_{livre/Terre}$. Même valeur, sens opposé.",
        "**Je vérifie le critère décisif.** Ces deux forces s'appliquent bien à **deux objets différents** : l'une au livre, l'autre à la Terre.",
        "**J'écarte la réaction de la table.** Elle s'exerce sur le livre, comme le poids : deux forces sur le même objet, qui se compensent. Ce n'est pas une paire action–réaction.",
        "**Ce que cela signifie.** Le livre attire vraiment la Terre, avec exactement la même force que la Terre l'attire. On ne le voit pas parce que la Terre est colossalement plus massive : la même force ne lui donne aucune variation de vitesse mesurable."],
  indice:"Inverse les deux noms de la force de départ : « la Terre agit sur le livre » devient…"},

 {id:"fo14", niveau:3, type:"num", enonce:"Une fusée éjecte ses gaz vers l'arrière avec une force de $2{,}4 × 10^{6}$ @u{N}. Quelle est la valeur de la force que les gaz exercent en retour sur la fusée, en @u{N} ?",
  rep:2.4e6, tol:1e4, unite:"N",
  diag:[{v:0, m:"Une force réciproque n'est jamais nulle. Si elle l'était, aucune fusée ne pourrait décoller — et c'est pourtant ainsi qu'elles avancent, y compris dans le vide où il n'y a rien contre quoi s'appuyer."},
        {v:1.2e6, m:"Tu as divisé par deux, comme si la force se partageait entre les deux corps. La troisième loi dit une **égalité** : chacun reçoit la force entière."},
        {v:4.8e6, m:"Tu as doublé. Les deux forces sont de même valeur, elles ne s'additionnent pas."},
        {v:2.4, m:"Tu as oublié le facteur $10^{6}$ : la force vaut $2{,}4 × 10^{6}$ @u{N}, pas $2{,}4$ @u{N}."}],
  corr:["**Ce que dit l'énoncé.** La fusée exerce sur les gaz une force de $2{,}4 × 10^{6}$ @u{N}, dirigée vers l'arrière.",
        "**La loi à appliquer.** Troisième loi de Newton : $@v{F}_{A/B} = - @v{F}_{B/A}$. Même valeur, sens opposé.",
        "**J'inverse les deux noms.** La fusée agit sur les gaz, donc les gaz agissent sur la fusée.",
        "**Je conclus sur la valeur.** Elle est identique : $2{,}4 × 10^{6}$ @u{N}. Seul le sens change — cette force-là est dirigée vers l'**avant**.",
        "**Je vérifie les objets.** L'une s'applique aux gaz, l'autre à la fusée : deux corps différents, comme il se doit.",
        "**Ce que cela explique.** C'est cette force vers l'avant, et elle seule, qui propulse la fusée. Elle n'a besoin de rien pour s'appuyer : c'est pour cela qu'une fusée fonctionne dans le vide, contrairement à ce qu'on imagine souvent."],
  indice:"La troisième loi énonce une égalité de valeurs : seule l'orientation change."},

 {id:"fo15", niveau:3, type:"num", unite:"N",
  enonce:"Le schéma ci-dessous représente les quatre forces qui s'exercent sur une caisse tirée sur le sol. Quelle est la valeur de la somme des forces ?",
  fig:{titre:"Document — bilan des forces sur la caisse", vue:[0,0,10,4.9], w:420, h:235,
       libre:true, grille:false, axes:false, objets:[
    {t:"sol", de:0.6, a:9.4, y:1.6, couleur:"ink3"},
    {t:"rect", x:4.4, y:1.6, w:1.2, h:1.5, couleur:"bleu"},
    {t:"vec", de:[5,2.35], a:[5,0.5], couleur:"ambre"},
    {t:"texte", x:5.9, y:0.85, txt:"P = 300 N", couleur:"ambre", taille:12},
    {t:"vec", de:[5,2.35], a:[5,4.2], couleur:"vert"},
    {t:"texte", x:5.9, y:4.05, txt:"R = 300 N", couleur:"vert", taille:12},
    {t:"vec", de:[5,2.35], a:[8.4,2.35], couleur:"bleu"},
    {t:"texte", x:8.2, y:3.05, txt:"F = 80 N", couleur:"bleu", taille:12},
    {t:"vec", de:[5,2.35], a:[3.7,2.35], couleur:"rouge"},
    {t:"texte", x:3.15, y:3.05, txt:"f = 30 N", couleur:"rouge", taille:12}
   ], note:"Deux forces verticales, deux forces horizontales. Les valeurs sont écrites à côté de chaque flèche. Attention : les flèches verticales et horizontales ne sont pas à la même échelle ; fie-toi aux valeurs écrites."},
  rep:50, tol:0.5,
  diag:[{v:0, m:"Les forces verticales se compensent, oui — mais pas les horizontales : $80$ @u{N} contre $30$ @u{N}. La somme n'est donc pas nulle."},
        {v:110, m:"Tu as additionné $80$ et $30$. Ces deux forces sont de sens **opposés** : elles se retranchent."},
        {v:710, m:"Tu as additionné les quatre valeurs. Une somme de forces n'est pas une somme de nombres : il faut tenir compte des directions et des sens."},
        {v:600, m:"Tu as additionné le poids et la réaction. Ces deux-là sont opposées et de même valeur : leur somme est nulle."}],
  corr:["**Ce que montre le document.** Quatre flèches partent du centre de la caisse. Deux sont verticales — le poids vers le bas, la réaction du sol vers le haut. Deux sont horizontales — la traction vers la droite, le frottement vers la gauche.",
        "**Le réflexe : séparer les directions.** On ne peut jamais additionner des forces de directions différentes comme des nombres. On traite d'abord la verticale, puis l'horizontale.",
        "**Étape 1 — la verticale.** $P = 300$ @u{N} vers le bas, $R = 300$ @u{N} vers le haut. Mêmes valeurs, sens opposés : elles se **compensent** exactement. Leur somme est nulle. C'est cohérent avec le fait que la caisse ne s'enfonce ni ne décolle.",
        "**Étape 2 — l'horizontale.** $F = 80$ @u{N} vers la droite, $f = 30$ @u{N} vers la gauche. Sens opposés, valeurs différentes : on **soustrait**. $80 - 30 = 50$ @u{N}, orientés vers la droite, du côté de la plus grande.",
        "**Étape 3 — je rassemble.** La somme des forces vaut $0$ à la verticale et $50$ @u{N} à l'horizontale : au total, $50$ @u{N} dirigés vers la droite.",
        "**Ce que cela m'apprend sur le mouvement.** La somme des forces n'est pas nulle : d'après le principe d'inertie, la caisse ne peut donc pas aller à vitesse constante. Elle **accélère vers la droite**, dans le sens de cette somme. Si l'on augmentait le frottement jusqu'à $80$ @u{N}, la somme deviendrait nulle et la caisse garderait la vitesse qu'elle a déjà."],
  indice:"Traite d'abord les deux forces verticales, puis les deux horizontales. Deux forces opposées se retranchent."},

 {id:"fo18", niveau:2, type:"qcm", enonce:"Deux billes de masses différentes sont lâchées de la même hauteur, au même instant, sans vitesse initiale, et l'on néglige l'air. Laquelle touche le sol la première ?",
  choix:["Elles touchent le sol en même temps","La plus lourde, car son poids est plus grand","La plus légère, car elle est plus facile à mettre en mouvement","Cela dépend de la hauteur de départ"],
  bonne:0,
  diag:["","La plus lourde subit bien un poids plus grand — mais elle est aussi plus difficile à mettre en mouvement, exactement dans la même proportion. Les deux effets se compensent.",
        "Elle est plus facile à mettre en mouvement, oui, mais elle est aussi attirée moins fort. Là encore, les deux effets s'annulent.",
        "La hauteur change la durée de la chute, bien sûr — mais elle est la même pour les deux billes. Elle ne peut donc pas les départager."],
  corr:["**Ce que demande la question.** Comparer les durées de chute de deux objets de masses différentes, lâchés dans les mêmes conditions.",
        "**Je pars de la deuxième loi de Newton.** $@f{Δ@v{v}}{Δt} = @f{Σ@v{F}}{m}$ : la variation de vitesse dépend de la force **et** de la masse.",
        "**J'écris la seule force en jeu.** En chute libre, c'est le poids, et le poids vaut $m@v{g}$ — il est lui-même proportionnel à la masse.",
        "**Je remplace, et je simplifie.** $@f{Δ@v{v}}{Δt} = @f{m@v{g}}{m} = @v{g}$. Le $m$ disparaît : la vitesse change de la même façon pour les deux billes.",
        "**Je conclus.** Même variation de vitesse, même hauteur, même instant de départ : elles arrivent ensemble.",
        "**Ce que cela recouvre.** C'est l'expérience de Galilée, et celle filmée sur la Lune en 1971 : un marteau et une plume lâchés ensemble touchent le sol au même instant, parce qu'il n'y a pas d'air. Sur Terre, la plume perd — non parce qu'elle est légère, mais parce que l'air la freine."],
  indice:"Écris la deuxième loi avec le poids $m@v{g}$ comme seule force, et regarde ce que devient la masse."}
]
}

]);
